#!/usr/bin/env python3
"""Seed prompts for categories 05-12."""
from pathlib import Path

ROOT = Path(__file__).parent.parent
PROMPTS = ROOT / "prompts"

def write(path: Path, content: str):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content.strip() + "\n")
    print(f"  ✍️  {path.relative_to(ROOT)}")

def make_prompt(category, title, tags, difficulty, prompt_text):
    models = ["claude-haiku-3-5", "claude-sonnet-4", "claude-opus-4", "claude-fable-5"]
    return f"""---
title: "{title}"
category: {category}
models: [{', '.join(models)}]
tags: [{', '.join(tags)}]
difficulty: {difficulty}
author: community
tested: true
---

## 🎯 Prompt

```
{prompt_text.strip()}
```

## 💡 Tips & Variations

- Works best with **Claude Sonnet 4** or **Fable 5**
- Adjust `[BRACKETED PLACEHOLDERS]` to your specific use case

## 🔗 Related Prompts

- See other prompts in this category: [README](README.md)
"""

# ─── CATEGORY 05: API DESIGN ────────────────────────────────────────────────────
cat = PROMPTS / "05-api-design"
api_design = [
  ("rest-design-principles.md","REST API Design from Scratch",["rest","api-design","best-practices"],"beginner","Design a REST API for [YOUR DOMAIN] from scratch applying every best practice:\n1. Resource naming (nouns, plural, nested where appropriate)\n2. HTTP methods (GET safe+idempotent, POST create, PUT replace, PATCH partial, DELETE)\n3. Status codes (cheat sheet for every case)\n4. Request/response shapes\n5. Error format (RFC 7807 Problem Details)\n6. Pagination, filtering, sorting query params\n7. Versioning strategy\n8. Authentication (Bearer JWT)\n9. Rate limiting headers\n10. HATEOAS links\n\nOutput: complete OpenAPI 3.1 YAML + sample cURL commands for every endpoint."),
  ("graphql-schema-design.md","GraphQL Schema Design Masterclass",["graphql","schema","api"],"advanced","Design a GraphQL schema for [YOUR DOMAIN].\n\nPrinciples to apply:\n1. Think in graphs, not endpoints\n2. Nullable vs non-nullable fields — when to use each\n3. Input types for mutations\n4. Connection pattern for pagination (edges, nodes, pageInfo)\n5. Interface and Union types for polymorphism\n6. Enum types for fixed values\n7. Custom scalars (Date, URL, JSON, Money)\n8. Subscription types for real-time\n9. Directives: @deprecated, @auth, @cacheControl\n10. Schema stitching vs federation for distributed systems\n\nOutput: complete SDL schema + example queries for each type."),
  ("api-versioning-strategy.md","API Versioning Strategy",["api","versioning","rest","strategy"],"intermediate","Define a complete API versioning strategy for my product:\n\nCurrent API users: [DESCRIBE YOUR CONSUMERS]\nBreaking change planned: [DESCRIBE WHAT'S CHANGING]\n\nCover:\n1. URL vs header vs query param — evaluate tradeoffs for my case\n2. SemVer for APIs: what constitutes major/minor/patch\n3. Backward compatibility rules (what is and isn't a breaking change)\n4. Deprecation process: sunset headers, docs notice, timeline\n5. Migration guide format for consumers\n6. Running multiple versions simultaneously\n7. Sunset monitoring: detect when old version traffic → 0\n8. Client SDK versioning strategy\n\nOutput: versioning policy document + implementation code."),
  ("grpc-vs-rest.md","Choose Between gRPC, REST, and GraphQL",["grpc","rest","graphql","architecture"],"advanced","Help me choose the right API style for my use case: [DESCRIBE YOUR SYSTEM: services, clients, requirements].\n\nProvide a rigorous comparison:\n\n| Criteria | REST | GraphQL | gRPC |\n|---|---|---|---|\n| Performance | | | |\n| Type safety | | | |\n| Browser support | | | |\n| Tooling | | | |\n| Learning curve | | | |\n| Caching | | | |\n| Schema evolution | | | |\n\nFor MY use case specifically:\n- Recommendation with justification\n- Where each would fail\n- Hybrid approach (if applicable)\n- Implementation starter for the recommended option"),
  ("openapi-spec.md","Write a Complete OpenAPI 3.1 Spec",["openapi","swagger","api","documentation"],"intermediate","Write a complete OpenAPI 3.1 specification for my API:\n\n[DESCRIBE YOUR API: purpose, main resources, auth method]\n\nInclude:\n1. `info` block with description and contact\n2. `servers` for development and production\n3. `securitySchemes` for your auth method\n4. All `paths` with every operation\n5. Request bodies with inline examples\n6. Response schemas for 200, 400, 401, 403, 404, 422, 500\n7. Reusable `components/schemas` (avoid repetition)\n8. Reusable `components/responses` for common errors\n9. Reusable `components/parameters`\n10. Webhook definitions (if applicable)\n\nOutput: valid YAML, importable into Postman or Swagger UI."),
  ("api-authentication.md","Design API Authentication Systems",["auth","api","jwt","oauth"],"advanced","Design the authentication system for my public API:\n\nConsumers: [3rd-party developers / mobile apps / other services]\nSecurity requirements: [DESCRIBE]\n\nDesign:\n1. API Key authentication: generation, storage (hashed), rotation\n2. JWT Bearer: access tokens, refresh, expiry\n3. OAuth 2.0: authorization code + PKCE for third-party apps\n4. HMAC request signing: for server-to-server (like AWS Signature)\n5. Rate limiting per auth method (API keys get higher limits)\n6. Scopes: define permission model for your API\n7. Token revocation\n8. Audit log: who accessed what and when\n\nOutput: auth spec document + implementation code for each method."),
  ("webhook-system.md","Design a Webhook Delivery System",["webhooks","api","events","reliability"],"advanced","Design and implement a production webhook system.\n\nMy service sends events when: [LIST YOUR EVENTS]\n\nConsumers register endpoints to receive these events.\n\nImplement:\n1. Webhook registration API (URL, events to subscribe, secret)\n2. Signature generation: HMAC-SHA256 of payload + timestamp\n3. Delivery: HTTP POST to consumer endpoint\n4. Retry: exponential backoff (1s, 5s, 30s, 5min, 30min, 2h, 12h, 24h)\n5. Dead letter: mark webhook as failed after all retries\n6. Delivery log: per-webhook history (status, response, attempts)\n7. Dashboard: consumer can view delivery log, replay events\n8. Verification guide: how consumers should verify signatures\n9. Event catalog: document every event type with example payload"),
  ("api-pagination.md","Design API Pagination",["pagination","api","rest","design"],"intermediate","Design comprehensive pagination for my API.\n\nResources to paginate: [LIST]\nExpected scale: [e.g., millions of records]\n\nImplement all patterns:\n1. **Offset pagination**: ?page=2&per_page=20 → simple, has limitations\n2. **Cursor pagination**: ?cursor=xxx&limit=20 → scalable, consistent\n3. **Keyset pagination**: ?after_id=xxx&after_created_at=xxx → for sorted multi-col\n4. **Seek pagination**: combining cursor + filters\n\nFor each:\n- SQL/query implementation\n- Response envelope shape (data, meta, links)\n- Total count: when to include, when to skip (expensive)\n- Frontend integration example\n- Performance characteristics\n\nRecommendation for my specific use case."),
  ("api-rate-limiting-design.md","Design API Rate Limiting",["rate-limiting","api","design","backend"],"advanced","Design a comprehensive rate limiting strategy for my public API.\n\nMy API plans:\n- Free: 1,000 req/day\n- Pro: 100,000 req/day  \n- Enterprise: unlimited (with fair-use)\n\nDesign:\n1. Algorithm: token bucket vs leaky bucket vs sliding window — which and why\n2. Granularity: global vs per-endpoint vs per-resource\n3. Cost model: assign cost to expensive operations (search=10x, AI=100x)\n4. Burst allowance: short bursts above limit without penalty\n5. Response headers: standard headers consumers should read\n6. 429 response body: clear message with retry timing\n7. Abuse prevention: detect and block abusive patterns\n8. Override: enterprise customers with custom limits\n\nOutput: rate limiting spec + Redis implementation."),
  ("api-error-handling.md","Design API Error Handling",["error-handling","api","rfc7807","rest"],"intermediate","Design a consistent error handling strategy for my REST API.\n\nFollowing RFC 7807 Problem Details:\n```json\n{\n  \"type\": \"https://api.example.com/errors/validation-error\",\n  \"title\": \"Validation Failed\",\n  \"status\": 422,\n  \"detail\": \"The request body contains invalid data.\",\n  \"instance\": \"/users/register\",\n  \"errors\": [{\"field\": \"email\", \"message\": \"Must be a valid email\"}]\n}\n```\n\nDesign:\n1. Error type registry (all possible error types with URLs)\n2. HTTP status code decision tree\n3. Validation errors: list all field errors\n4. Business logic errors: meaningful codes (INSUFFICIENT_FUNDS, USER_SUSPENDED)\n5. Internal errors: never leak stack traces\n6. Rate limit errors: include retry timing\n7. Client SDK: parse errors into typed exceptions\n8. Monitoring: every 5xx triggers an alert"),
  ("api-caching.md","Design API Caching Strategy",["caching","api","http","etag"],"advanced","Design a comprehensive caching strategy for my API.\n\nEndpoints: [LIST YOUR ENDPOINTS AND HOW OFTEN DATA CHANGES]\n\nHTTP caching:\n1. `Cache-Control` headers for each endpoint type\n2. `ETag` implementation (conditional GET, 304 responses)\n3. `Last-Modified` header\n4. `Vary` header for content negotiation\n5. CDN caching: which endpoints to cache at edge\n6. Cache invalidation on data change\n\nServer-side caching:\n7. Redis cache for expensive queries\n8. Cache warming strategy\n9. Cache aside vs write-through vs write-behind\n\nClient-side:\n10. React Query cache coordination with HTTP cache\n\nOutput: cache policy per endpoint type + implementation code."),
  ("api-testing-strategy.md","Design API Testing Strategy",["testing","api","contract","postman"],"intermediate","Design a comprehensive testing strategy for my API.\n\nAPI type: [REST / GraphQL] with [N] endpoints\n\nLayers:\n1. **Unit tests**: test each service/business logic function in isolation\n2. **Integration tests**: test route → controller → service → real DB\n3. **Contract tests**: verify API matches OpenAPI spec (Dredd or Spectral)\n4. **E2E tests**: test complete user flows via API (Postman collections)\n5. **Performance tests**: k6 load test for critical endpoints (target: 1000 RPS)\n6. **Security tests**: OWASP ZAP scan, auth bypass attempts\n7. **Fuzzing**: send random/malformed inputs to all endpoints\n\nCoverage targets per layer.\nCI pipeline: run all layers on each PR.\nOutput: test strategy document + example tests for each layer."),
  ("api-sdk-design.md","Design and Build an API SDK",["sdk","api","typescript","client"],"advanced","Design and build a TypeScript SDK for my API.\n\nAPI: [DESCRIBE YOUR API]\n\nSDK design principles:\n1. **Type safety**: TypeScript types for all requests and responses\n2. **Fluent interface**: `client.users.create({...}).then()`\n3. **Resource-based**: `client.users`, `client.products`\n4. **Consistent error handling**: typed error classes\n5. **Retry logic**: built-in retry with backoff\n6. **Pagination helpers**: auto-paginate with async iterators\n7. **Request/response interceptors**: for logging, auth refresh\n8. **Config**: base URL, API key, timeout, retries\n9. **Framework-agnostic**: works in Node.js and browser\n10. **Zero dependencies**: or minimal deps\n\nOutput: complete SDK + README + usage examples."),
  ("hypermedia-api.md","Build a Hypermedia (HATEOAS) API",["hateoas","rest","hypermedia","api"],"advanced","Implement HATEOAS for my REST API to make it truly discoverable.\n\nResources: [LIST YOUR MAIN RESOURCES]\n\nImplement:\n1. `_links` in every response (self, related resources, actions)\n2. Link relations using IANA-registered names (collection, item, edit, etc.)\n3. `_actions` for available operations on this resource based on current state\n4. Embedded resources (avoid extra round trips)\n5. API root: GET / returns all available resources\n6. HAL (Hypertext Application Language) format\n7. Link templates (RFC 6570) for parameterized links\n8. Siren or JSON:API as alternatives — compare\n\nExample: Order resource with links to: payment, shipment, cancel (only if cancellable), invoice."),
  ("api-monitoring.md","Monitor Your API in Production",["monitoring","api","apm","observability"],"advanced","Set up comprehensive monitoring for my production API.\n\nCurrent setup: [DESCRIBE YOUR STACK]\n\nMetrics to track:\n1. **Availability**: uptime percentage (target: 99.9%)\n2. **Latency**: p50, p95, p99 response times per endpoint\n3. **Error rate**: 4xx and 5xx rates separately\n4. **Throughput**: requests per second over time\n5. **Saturation**: CPU, memory, DB connections\n\nAlerting:\n6. Error rate > 1% for 5 minutes → PagerDuty\n7. p95 latency > 500ms → Slack\n8. Uptime drops → immediate alert\n\nTools: Prometheus + Grafana (self-hosted) or DataDog (managed)\n\nOutput: dashboard JSON + alerting rules + runbook template."),
  ("streaming-api.md","Design a Streaming API",["streaming","api","sse","ndjson"],"advanced","Design a streaming API for: [USE CASE — AI responses / data export / live events].\n\nOptions to evaluate:\n1. **Server-Sent Events**: unidirectional, browser-native, auto-reconnect\n2. **WebSocket**: bidirectional, lower overhead\n3. **gRPC streaming**: binary, typed, low latency\n4. **NDJSON over HTTP**: newline-delimited JSON, simple\n5. **HTTP chunked transfer**: progressive loading\n\nFor MY use case, implement:\n- Server implementation\n- Client (browser + Node.js) SDK\n- Backpressure handling\n- Error recovery\n- Authentication\n- Progress reporting\n- Cancellation\n\nWith concrete code examples for each layer."),
  ("api-deprecation.md","Deprecate API Endpoints Gracefully",["api","deprecation","versioning","lifecycle"],"intermediate","Plan and execute graceful deprecation of these API endpoints:\n\n[LIST ENDPOINTS TO DEPRECATE AND THEIR REPLACEMENTS]\n\nDeprecation process:\n1. Add `Deprecation` and `Sunset` headers (RFC 8594)\n2. Update docs with deprecation notice + migration guide\n3. Log usage of deprecated endpoints (to track migration progress)\n4. Email API consumers who have called the endpoint recently\n5. Show deprecation warning in developer dashboard\n6. Hard cutoff date announcement (3-6 months notice)\n7. Grace period extension process for consumers who need more time\n8. Traffic monitoring: graph call volume trending to zero\n9. Actual removal + 410 Gone response\n10. Post-mortem: how many consumers were impacted"),
  ("idempotency-design.md","Design Idempotent API Operations",["idempotency","api","reliability","payments"],"advanced","Design idempotent API operations for my payment-critical system.\n\nCritical operations: [LIST YOUR OPERATIONS]\n\nImplement:\n1. `Idempotency-Key` header specification (UUID format, required for mutations)\n2. Key storage: Redis with TTL (24h) + database for permanent record\n3. Response caching: first successful response cached and returned on retry\n4. In-flight protection: Redis lock during processing\n5. Key fingerprinting: cache key = idempotency-key + request body hash\n6. What to do if same key but different body (reject with 422)\n7. Conditional requests: ETag + If-Match for read-modify-write\n8. Testing: how to simulate retry scenarios\n9. Client retry logic: when to retry and when not to\n10. Documentation: how to communicate this to API consumers"),
  ("api-gateway-design.md","Design an API Gateway",["api-gateway","kong","nginx","architecture"],"advanced","Design an API gateway for my microservices architecture.\n\nServices: [LIST YOUR SERVICES]\nClients: [Web app, Mobile app, Third-party]\n\nGateway responsibilities:\n1. **Routing**: path-based and header-based routing rules\n2. **Auth**: JWT validation, API key management\n3. **Rate limiting**: per client, per service, per endpoint\n4. **Load balancing**: round-robin, weighted, least-connections\n5. **Circuit breaker**: fail fast when upstream is unhealthy\n6. **Caching**: cache GET responses at edge\n7. **Transformation**: request/response manipulation\n8. **Observability**: request tracing, access logs, metrics\n9. **TLS termination**: HTTPS → HTTP to services\n10. **DDoS protection**: IP blocking, challenge-based\n\nTool: Kong (open source) or Nginx + Lua, with config files."),
  ("api-contract-testing.md","Implement API Contract Testing",["contract-testing","pact","testing","api"],"advanced","Implement consumer-driven contract testing for my API ecosystem.\n\nProvider: [YOUR API SERVICE]\nConsumers: [FRONTEND APP, MOBILE APP, THIRD-PARTY SERVICE]\n\nUsing: Pact (consumer-driven contract testing)\n\n1. Consumer writes a contract: \"I expect this request to return this response shape\"\n2. Contract published to Pact Broker\n3. Provider verifies against the contract in CI\n4. If contract breaks, CI fails — immediate feedback\n\nImplement:\n- Consumer contract test (JavaScript/TypeScript)\n- Provider verification (Node.js)\n- Pact Broker setup (Docker)\n- CI integration (GitHub Actions)\n- Versioning contracts with semantic versioning\n- \"Can I Deploy\" check before production deploy"),
  ("api-load-testing.md","Load Test Your API",["load-testing","k6","performance","api"],"intermediate","Design and run a comprehensive load test for my API.\n\nAPI to test: [DESCRIBE YOUR API]\nPerformance targets: [e.g., 1000 RPS, p99 < 200ms, error rate < 0.1%]\n\nUsing: k6\n\n1. Baseline test: 1 user, 30s — establish baseline latency\n2. Load test: ramp to 1000 VUs over 5min, sustain 10min\n3. Spike test: instant jump to 10x normal traffic\n4. Stress test: find breaking point (keep increasing until failure)\n5. Soak test: moderate load for 24h (find memory leaks)\n\nFor each test:\n- k6 script with realistic scenarios (not just one endpoint)\n- Metrics to capture\n- Pass/fail thresholds\n- Results interpretation\n\nOutput: k6 scripts + Grafana dashboard for results."),
  ("api-documentation-design.md","Design Developer Documentation",["docs","api","developer-experience","dx"],"intermediate","Design world-class developer documentation for my API.\n\nAPI: [DESCRIBE]\nTarget developers: [SKILL LEVEL AND BACKGROUND]\n\nDocumentation structure:\n1. **Getting Started**: auth → first API call → see result (< 5 minutes)\n2. **Guides**: common use cases as step-by-step tutorials\n3. **Reference**: every endpoint, parameter, response (auto-generated from OpenAPI)\n4. **Changelog**: what changed in each version\n5. **Migration guides**: how to upgrade from v1 to v2\n6. **SDKs**: code examples in 5 languages for every endpoint\n7. **Playground**: try API calls in the browser\n8. **Status page**: link to uptime page\n9. **Error reference**: every error code with solution\n10. **Community**: Discord/forum link\n\nTool: Mintlify, Readme.io, or Docusaurus."),
  ("event-driven-api.md","Design an Event-Driven API",["events","api","kafka","event-sourcing"],"advanced","Design an event-driven API architecture.\n\nMy domain: [DESCRIBE]\n\nEvent catalog (define all events):\n1. Event naming convention: `[domain].[entity].[past-tense-verb]`\n2. Event schema with: id, type, source, time, data, correlationId\n3. Schema registry: version events, prevent breaking changes\n4. Event taxonomy: Domain Events vs Integration Events vs Commands\n\nAPI patterns:\n5. **Event sourcing**: store events, derive state → audit log for free\n6. **CQRS**: separate read model (optimized query) from write model (events)\n7. **Choreography**: services react to events (no central orchestrator)\n8. **Orchestration**: saga pattern for multi-step business processes\n\nImplementation: Kafka or RabbitMQ + Node.js/Python consumers."),
  ("api-gateway-rate-limiting.md","Implement Advanced API Gateway Rate Limiting",["api-gateway","rate-limiting","kong","nginx"],"advanced","Implement sophisticated rate limiting at the API gateway level.\n\nGateway: [Kong / Nginx / Cloudflare Workers]\n\nRate limiting tiers:\n- Anonymous: 100 req/min per IP\n- Free account: 1,000 req/hour\n- Pro account: 50,000 req/hour\n- Enterprise: custom\n\nAdvanced features:\n1. Cost-based limiting (not just request count)\n2. Endpoint-specific limits (POST /ai-generate = 10x cost)\n3. Global vs per-region limits\n4. DDoS protection: detect and block attack patterns\n5. Whitelisting: internal services bypass limits\n6. Rate limit sharing across microservices\n7. Graceful degradation: partial service when near limit\n\nRedis cluster configuration for distributed state."),
  ("graphql-best-practices.md","GraphQL API Best Practices",["graphql","best-practices","api","performance"],"advanced","Apply GraphQL best practices to my schema: [DESCRIBE YOUR SCHEMA].\n\n1. **Schema design**: self-documenting, expressive types\n2. **Naming**: consistent conventions (camelCase fields, PascalCase types)\n3. **Nullability**: when to use ! — prefer nullable for forward compatibility\n4. **Pagination**: Relay connection spec (avoid arrays for paginated data)\n5. **Mutations**: one input type per mutation, return the mutated type\n6. **Error handling**: errors as data vs GraphQL errors\n7. **N+1 prevention**: DataLoader pattern, every resolver uses DataLoader\n8. **Depth limiting**: prevent deeply nested queries (denial of service)\n9. **Query complexity analysis**: score queries, reject too-complex ones\n10. **Persisted queries**: hash-based for production (security + performance)\n11. **Field deprecation**: @deprecated with migration notes\n12. **Authorization**: never trust client, check auth in every resolver"),
  ("api-security.md","Secure Your API Against Common Attacks",["security","api","owasp","backend"],"advanced","Harden my API against the OWASP API Security Top 10.\n\nMy API: [DESCRIBE]\n\n1. **Broken Object Level Auth (BOLA)**: verify ownership on every request\n2. **Broken Auth**: JWT best practices, no weak secrets\n3. **Broken Object Property Level Auth**: never expose more fields than needed\n4. **Unrestricted Resource Consumption**: rate limiting, pagination limits\n5. **Broken Function Level Auth**: re-verify role on admin operations\n6. **Unrestricted Access to Sensitive Business Flows**: apply stricter limits\n7. **Server Side Request Forgery**: validate and allowlist URLs\n8. **Security Misconfiguration**: headers, CORS, debug endpoints\n9. **Improper Inventory Management**: disable unused endpoints\n10. **Unsafe Consumption of APIs**: validate third-party API responses\n\nFor each: code example of the vulnerability + the fix."),
  ("rest-api-design-critique.md","Critique and Improve an Existing REST API",["rest","api","critique","refactoring"],"intermediate","Review and critique this REST API design:\n\n[PASTE YOUR API ROUTES AND SCHEMAS]\n\nAnalyze:\n1. URL design issues (verbs in URLs, inconsistent naming)\n2. HTTP method misuse (GET with side effects, POST for everything)\n3. Status code problems (200 for errors, 500 for everything)\n4. Response shape inconsistencies\n5. Missing pagination, filtering, sorting\n6. Auth vulnerabilities\n7. Missing error details\n8. Performance issues (no caching headers, N+1 in related data)\n9. Breaking change risks in current design\n10. Security gaps\n\nFor each issue: severity (critical/major/minor), explanation, and the fix.\nOutput: improved API spec."),
  ("graphql-federation.md","Set Up GraphQL Federation",["graphql","federation","microservices","apollo"],"advanced","Set up Apollo GraphQL Federation for my microservices.\n\nServices:\n- [Service 1]: owns [ENTITIES]\n- [Service 2]: owns [ENTITIES]\n- [Service 3]: owns [ENTITIES]\n\nImplement:\n1. Gateway: Apollo Router or Apollo Server Gateway\n2. Subgraph setup for each service\n3. Entity definition: @key directive on shared types\n4. Reference resolver: resolve entities from other subgraphs\n5. Extend types across subgraphs\n6. Federated subscriptions\n7. Auth: propagate token from gateway to subgraphs\n8. Performance: query planning and batching\n9. Supergraph schema composition\n10. Schema checks: validate before deploying\n\nWith Docker Compose for local development."),
  ("api-backwards-compatibility.md","Maintain API Backwards Compatibility",["api","compatibility","versioning","design"],"advanced","Define rules for maintaining backwards compatibility in my API.\n\nCurrent consumers: [DESCRIBE]\n\nNon-breaking changes (safe to ship):\n1. Add new optional fields to responses\n2. Add new optional request fields\n3. Add new endpoints\n4. Add new enum values (caution)\n5. Increase rate limits\n\nBreaking changes (require versioning or careful migration):\n6. Remove/rename fields\n7. Change field types\n8. Change auth requirements\n9. Change response codes\n10. Make optional fields required\n\nFor each potential breaking change in my API:\n- Is it actually breaking?\n- If yes: expand-contract migration pattern\n- Testing: contract tests to detect regressions\n\nOutput: compatibility policy + API change checklist."),
  ("api-design-patterns.md","API Design Patterns Masterclass",["api","patterns","design","best-practices"],"advanced","Apply these API design patterns to my API: [DESCRIBE YOUR API].\n\n1. **Resource Singleton**: `/me` instead of `/users/{id}` for current user\n2. **Sub-resources**: `/posts/{id}/comments` for owned resources\n3. **Custom methods**: `/orders/{id}:cancel` (Google API style) for actions\n4. **Long-running operations**: return operation ID → poll for status\n5. **Batch operations**: `POST /batch` to reduce round trips\n6. **Partial updates**: PATCH with RFC 7396 JSON Merge Patch\n7. **Field selection**: `?fields=id,name,email` to reduce payload\n8. **Sorting**: `?sort=-createdAt,+name`\n9. **Includes/expansion**: `?include=author,comments` to embed related\n10. **Search endpoint**: POST /search with complex query body\n\nFor each: when to use + implementation."),
  ("api-telemetry.md","Add Distributed Tracing to APIs",["tracing","opentelemetry","observability","api"],"advanced","Add distributed tracing across my API services using OpenTelemetry.\n\nServices: [LIST YOUR SERVICES AND THEIR STACK]\n\nImplement:\n1. OpenTelemetry SDK setup in each service (Node.js + Python examples)\n2. Trace context propagation (W3C TraceContext headers)\n3. Auto-instrumentation: HTTP, DB, Redis, message queues\n4. Manual spans for business-critical operations\n5. Trace attributes: user ID, request ID, customer tier\n6. Sampling: 100% in dev, 10% in prod (head-based sampling)\n7. Export to Jaeger (open source) or DataDog APM\n8. Baggage: propagate tenant ID across service boundaries\n\nVisualize: trace waterfall showing where time is spent."),
  ("api-changelog.md","Manage Your API Changelog",["changelog","api","versioning","documentation"],"beginner","Create and maintain a professional API changelog.\n\nMy API: [DESCRIBE]\nChanges this release: [LIST CHANGES]\n\nChangelog format:\n```\n## [2.4.0] - 2026-01-15\n### Added\n- `GET /users/{id}/activity` endpoint\n### Changed  \n- `created_at` field is now an ISO 8601 string (was Unix timestamp)\n### Deprecated\n- `GET /users/{id}/feed` (use `GET /feed?user_id={id}` instead, sunset: 2026-07-01)\n### Removed\n- `POST /auth/token` (was deprecated in 2.0.0)\n### Fixed\n- Pagination cursor now works correctly with filters applied\n### Security\n- Fixed IDOR vulnerability in document access control\n```\n\nAlso: how to:\n1. Automate changelog from conventional commits\n2. Notify API consumers of changes\n3. Maintain breaking change log separately"),
  ("api-mocking.md","Mock External APIs for Development and Testing",["mocking","msw","testing","api"],"intermediate","Set up comprehensive API mocking for development and testing.\n\nExternal APIs I use: [LIST THIRD-PARTY APIS]\n\nUsing: Mock Service Worker (MSW)\n\n1. Handler setup: intercept matching requests\n2. Realistic mock data using Faker.js\n3. Simulated network delay and errors\n4. Conditional responses: different responses based on request body\n5. Stateful mocks: cart that accumulates items\n6. Passthrough: let some requests hit real API\n7. Browser vs Node.js setup\n8. Integration with React Testing Library\n9. Integration with Vitest\n10. Toggle mocks with environment variable\n\nAlso: WireMock for Java, nock for Node.js, VCR for Ruby — comparison."),
  ("api-client-generation.md","Auto-Generate API Clients from OpenAPI",["openapi","codegen","sdk","typescript"],"intermediate","Auto-generate typed API clients from my OpenAPI specification.\n\nMy OpenAPI spec: [PATH OR PASTE]\nTarget languages: TypeScript, Python, Kotlin (Android)\n\nUsing: openapi-generator-cli or openapi-typescript\n\n1. TypeScript client: openapi-typescript + openapi-fetch\n   - Zero-runtime-overhead types\n   - Fetch-based, works everywhere\n   - Tree-shakeable\n2. Python client: openapi-generator\n   - Pydantic models for responses\n   - Async (httpx) version\n3. React Query integration: tanstack-query-openapi\n   - Auto-generated hooks per endpoint\n\nOutput: generator config + GitHub Actions to regenerate on spec change."),
  ("webhook-security.md","Secure Webhook Endpoints",["webhooks","security","api","hmac"],"intermediate","Secure my webhook-receiving endpoints against abuse and spoofing.\n\nWebhooks I receive from: [LIST: Stripe, GitHub, Twilio, etc.]\n\nFor each webhook provider:\n1. Signature verification (HMAC-SHA256, provider-specific header)\n2. Timestamp validation (reject webhooks > 5 minutes old)\n3. Raw body parsing (not parsed JSON — signature is over raw bytes)\n4. Idempotency: deduplicate events using event ID\n5. Async processing: immediately return 200, process in queue\n6. Retry handling: idempotent handlers for safe retries\n7. Error handling: return 4xx only if payload is invalid (causes retries)\n8. Monitoring: alert on missing expected webhooks\n9. Testing: replay webhooks from provider dashboard\n10. Webhook signing secret rotation procedure"),
  ("api-data-transformation.md","Transform API Data Shapes",["transformation","api","typescript","mapping"],"intermediate","Design a data transformation layer for my API.\n\nProblem: my database models don't match what my API consumers need.\n\nDB model: [DESCRIBE]\nAPI response needed: [DESCRIBE DIFFERENCES]\n\nImplement:\n1. Serializer pattern: db_model → api_response\n2. Deserializer: api_request → db_model\n3. Field renaming: snake_case → camelCase\n4. Field filtering: hide internal fields\n5. Field addition: compute derived fields\n6. Nested objects: embed related models\n7. Type coercion: convert timestamps, enums, nulls\n8. TypeScript types: end-to-end type safety\n9. Versioned serializers: v1 and v2 output from same DB\n10. Partial responses: honor `?fields=` param"),
  ("async-api-design.md","Design Asynchronous API Operations",["async","api","webhooks","polling"],"advanced","Design async operation handling for my API.\n\nOperations that are slow (> 5 seconds): [LIST]\n\nPattern 1 — Polling:\n1. POST /export → 202 Accepted + `{job_id, status_url}`\n2. GET /jobs/{id} → {status: pending|processing|done|failed, result_url}\n3. Client polls with exponential backoff\n4. Result available for 24h then deleted\n\nPattern 2 — Webhooks:\n5. Client registers webhook URL\n6. On completion: POST to webhook with result\n\nPattern 3 — WebSocket / SSE:\n7. Connect before starting job\n8. Receive real-time progress events\n\nFor MY specific operations: which pattern to use and why.\nImplementation for each."),
  ("api-mock-server.md","Build a Production-Like Mock Server",["mock","api","prism","testing"],"intermediate","Build a comprehensive mock API server for my frontend team.\n\nMy API spec: [OPENAPI YAML or description]\n\nUsing: Prism (from Stoplight) — generate mock from OpenAPI automatically\n\n1. Serve mock from OpenAPI spec: `prism mock api.yaml`\n2. Dynamic examples: not just static examples from spec\n3. Validation: validate requests against spec (reject invalid requests)\n4. Proxy mode: real requests with recording for future mocks\n5. Scenarios: different responses based on request params\n6. Stateful mocking: maintain state between requests\n7. Docker: run mock server in CI\n8. Delay simulation: add realistic latency\n9. Error scenarios: force specific error codes\n10. Team sharing: host mock server for entire frontend team"),
  ("graphql-subscriptions.md","Implement GraphQL Subscriptions",["graphql","subscriptions","websockets","real-time"],"advanced","Implement GraphQL subscriptions for real-time features.\n\nReal-time features needed: [DESCRIBE]\n\nUsing: Apollo Server + graphql-ws\n\n1. Subscription schema definition\n2. PubSub setup (in-memory for single server, Redis for multiple)\n3. Resolver: publish events + subscribe to topics\n4. Authentication: verify JWT on WebSocket connection\n5. Authorization: filter subscription events per user\n6. Connection lifecycle: onConnect, onSubscribe, onDisconnect\n7. Error handling: close connection on auth failure\n8. Reconnection: client auto-reconnects with same subscription\n9. Scaling: Redis PubSub adapter for horizontal scaling\n10. Testing: subscription tests with graphql-ws client\n\nClient implementation: React hook with Apollo Client."),
  ("api-standards.md","Define Internal API Standards",["api","standards","team","documentation"],"intermediate","Create internal API standards for my engineering team.\n\nTeam size: [N engineers], building [N microservices]\n\nStandards document covering:\n1. **URL conventions**: naming, nesting, parameter formats\n2. **HTTP method semantics**: team agreement on GET/POST/PUT/PATCH/DELETE\n3. **Status codes**: company-wide lookup table\n4. **Error format**: mandatory fields, optional fields\n5. **Auth method**: which auth per use case\n6. **Pagination**: single standard (cursor-based)\n7. **Date format**: ISO 8601 everywhere, always UTC\n8. **Naming**: camelCase JSON fields, English only\n9. **Versioning**: when and how to version\n10. **Documentation**: what must be documented before shipping\n\nOutput: API Standards v1.0 document for team adoption."),
  ("api-lifecycle.md","Manage the Full API Lifecycle",["api","lifecycle","devops","strategy"],"advanced","Manage my API's full lifecycle from design to sunset.\n\nMy API: [DESCRIBE]\n\nPhases:\n1. **Design**: API-first — spec before code, review with stakeholders\n2. **Mock**: generate mock server from spec for parallel dev\n3. **Develop**: implement against spec, linting to verify conformance\n4. **Test**: contract testing, integration tests, security scan\n5. **Document**: auto-generate from spec + hand-written guides\n6. **Release**: semantic versioning, changelog, consumer notification\n7. **Monitor**: uptime, latency, error rates, usage analytics\n8. **Iterate**: gather consumer feedback, add features without breaking\n9. **Deprecate**: announce sunset, provide migration path\n10. **Sunset**: remove old version, redirect to new\n\nTool recommendations for each phase."),
  ("api-design-review.md","Conduct an API Design Review",["api","design-review","best-practices","team"],"intermediate","Conduct a thorough API design review for this proposed API:\n\n[PASTE YOUR PROPOSED API DESIGN]\n\nReview checklist:\n□ Resource naming follows conventions\n□ HTTP methods are semantically correct\n□ Status codes are appropriate\n□ Error responses are consistent\n□ Pagination is implemented correctly\n□ Auth is secure and consistent\n□ Rate limiting is planned\n□ Versioning strategy is defined\n□ Breaking changes are identified\n□ Documentation is planned\n□ Security: no sensitive data in URLs\n□ CORS is properly configured\n□ Backwards compatibility is maintained\n□ Performance: no N+1 in response shapes\n□ Idempotency on critical operations\n\nFor each failing item: why it fails and how to fix it."),
  ("api-playground.md","Build an API Playground",["api","playground","developer-experience","ui"],"intermediate","Build an interactive API playground for my API (like Stripe's API explorer).\n\nMy API: [DESCRIBE]\n\nFeatures:\n1. Request builder: select method, endpoint, fill params/body\n2. Auth: enter API key or use OAuth to get a token\n3. Environment selector: sandbox vs production\n4. Code generation: copy the request as cURL, JavaScript, Python, Ruby\n5. Response viewer: formatted JSON, headers, status code\n6. Request history: last 50 requests\n7. Saved requests: name and save common requests\n8. Schema viewer: explore all available endpoints with docs\n9. Example responses: pre-loaded realistic examples\n10. Dark mode\n\nStack: React + Monaco Editor (for JSON body) + fetch API."),
]

for filename, title, tags, difficulty, prompt_text in api_design:
    write(cat / filename, make_prompt("api-design", title, tags, difficulty, prompt_text))

# ─── CATEGORY 06: DATABASE DESIGN ──────────────────────────────────────────────
cat = PROMPTS / "06-database-design"
db_design = [
  ("er-diagram.md","Design a Database Schema",["postgresql","schema","erd","modeling"],"intermediate","Design a complete database schema for: [YOUR APPLICATION].\n\nOutput:\n1. Entity-Relationship Diagram (ASCII art or Mermaid)\n2. CREATE TABLE SQL for each entity with:\n   - Correct data types (prefer specific: UUID, TEXT, TIMESTAMPTZ, NUMERIC, BOOLEAN)\n   - NOT NULL constraints where appropriate\n   - DEFAULT values\n   - CHECK constraints\n   - UNIQUE constraints\n   - Foreign keys with ON DELETE behavior\n3. Indexes (beyond primary key)\n4. Rationale for each major design decision\n5. Alternative designs considered and why rejected\n\nNormalization target: 3NF unless denormalization is justified."),
  ("postgresql-advanced.md","Advanced PostgreSQL Features",["postgresql","advanced","sql","database"],"advanced","Implement these advanced PostgreSQL features in my database:\n\nUse case: [DESCRIBE YOUR DATA AND QUERIES]\n\n1. **JSONB**: store and query semi-structured data, GIN index, jsonb_path operators\n2. **Full-text search**: tsvector, tsquery, GIN index, ts_rank, tsheadline\n3. **Partitioning**: range/list/hash partitioning, partition pruning\n4. **CTEs**: WITH clause, recursive CTEs for tree structures\n5. **Window functions**: ROW_NUMBER, RANK, LEAD/LAG, running totals\n6. **Materialized views**: refresh strategy, incremental refresh\n7. **Foreign Data Wrappers**: query external PostgreSQL or CSV\n8. **Triggers and rules**: computed columns, audit log\n9. **Extensions**: pg_stat_statements, pgcrypto, postgis\n10. **EXPLAIN ANALYZE**: read and optimize query plans"),
  ("mongodb-schema.md","Design a MongoDB Schema",["mongodb","nosql","schema","document"],"intermediate","Design an optimal MongoDB schema for: [YOUR APPLICATION].\n\nDecisions to make:\n1. **Embed vs Reference**: when to embed documents vs use references (show examples)\n2. **One-to-one**: how to model (embed in most cases)\n3. **One-to-many**: embed array vs separate collection — decide based on cardinality\n4. **Many-to-many**: junction document pattern vs array of IDs\n5. **Polymorphism**: different document shapes in one collection\n6. **Bucket pattern**: time-series data optimization\n7. **Outlier pattern**: handle exceptional large documents\n8. **Indexes**: compound, text, geo, sparse, partial\n9. **Aggregation pipeline**: for your main queries\n10. **Transactions**: when MongoDB transactions are needed\n\nSQL vs MongoDB decision: justify the choice for this use case."),
  ("sql-query-optimization.md","Optimize Slow SQL Queries",["sql","optimization","indexes","postgresql"],"advanced","Optimize these slow SQL queries:\n\n[PASTE YOUR SLOW QUERIES AND THEIR EXPLAIN ANALYZE OUTPUT]\n\nOptimization techniques:\n1. **Read EXPLAIN ANALYZE**: identify seq scan, hash join, sort spills\n2. **Index creation**: B-tree, GIN, GiST, partial, covering indexes\n3. **Query rewriting**: EXISTS vs IN, CTEs vs subqueries, avoiding DISTINCT\n4. **JOIN optimization**: order, type (hash/nested loop/merge), conditions\n5. **Filter pushdown**: move WHERE conditions to reduce rows early\n6. **N+1 elimination**: single JOIN vs multiple queries\n7. **Pagination**: cursor-based vs OFFSET\n8. **Materialized views**: precompute expensive aggregations\n9. **Statistics**: ANALYZE, pg_stats for planner accuracy\n10. **Partitioning**: for very large tables\n\nBefore/after EXPLAIN ANALYZE comparison."),
  ("database-indexing.md","Master Database Indexing",["indexes","postgresql","performance","sql"],"advanced","Design the optimal index strategy for my database.\n\nSchema: [PASTE YOUR TABLES]\nFrequent queries: [DESCRIBE OR PASTE YOUR TOP 10 QUERIES]\n\n1. **When to index**: high cardinality, frequent WHERE, JOIN, ORDER BY\n2. **When NOT to index**: write-heavy tables, low cardinality, small tables\n3. **B-tree indexes**: default, range queries, equality\n4. **Composite indexes**: column order matters — explain how\n5. **Partial indexes**: index WHERE condition (only index what you query)\n6. **Covering indexes**: INCLUDE extra columns to avoid table lookup\n7. **GIN indexes**: for arrays, JSONB, full-text search\n8. **Index bloat**: REINDEX, VACUUM impact\n9. **Unused indexes**: find and drop them (pg_stat_user_indexes)\n10. **Index-only scans**: when possible\n\nOutput: exact CREATE INDEX statements for my queries."),
  ("redis-data-modeling.md","Model Data in Redis",["redis","data-modeling","nosql","caching"],"advanced","Model and store this data efficiently in Redis:\n\nData: [DESCRIBE YOUR DATA]\nAccess patterns: [DESCRIBE HOW YOU QUERY IT]\n\nRedis data structures:\n1. **String**: simple key-value, counters, cached JSON\n2. **Hash**: user objects, settings (field-level access)\n3. **List**: queues, recent items, activity feeds\n4. **Set**: unique values, tags, set operations (union/intersect/diff)\n5. **Sorted Set**: leaderboards, scheduled tasks, range queries\n6. **Stream**: append-only log, event sourcing, message queue\n7. **HyperLogLog**: approximate unique count (< 1% error, constant memory)\n8. **Bloom Filter**: membership test without false negatives\n9. **Geo**: store and query locations, find nearby\n10. **JSON** (RedisJSON): store/query JSON documents\n\nKey naming conventions + TTL strategy for each."),
  ("data-migration.md","Plan and Execute Data Migration",["migration","postgresql","etl","data"],"advanced","Plan and execute a data migration for: [DESCRIBE WHAT YOU'RE MIGRATING — e.g., old schema to new schema, MySQL to PostgreSQL, adding columns].\n\n1. **Migration plan**:\n   - What data is moving where\n   - Estimated volume and time\n   - Zero-downtime vs maintenance window approach\n2. **Backup strategy**: full backup before starting, point-in-time recovery test\n3. **Migration script**: idempotent, can be re-run safely\n4. **Validation**: verify row counts, checksums, sample records\n5. **Dual-write period**: write to old and new schema simultaneously\n6. **Cutover**: atomic switch, rollback plan if issues\n7. **Cleanup**: remove old schema after validation period\n8. **Testing**: run migration on production data copy first\n\nOutput: complete migration SQL + validation queries."),
  ("database-normalization.md","Normalize a Database Schema",["normalization","sql","schema","design"],"intermediate","Normalize this database schema to 3NF (Third Normal Form):\n\n[PASTE YOUR CURRENT SCHEMA — especially if it has JSON columns, repeated data, or one giant table]\n\nProcess:\n1. **1NF**: eliminate repeating groups, ensure atomic values\n2. **2NF**: eliminate partial dependencies (all non-key fields depend on full PK)\n3. **3NF**: eliminate transitive dependencies\n4. **BCNF**: Boyce-Codd Normal Form if needed\n\nFor each step:\n- Identify the violation\n- The SQL to fix it\n- The tradeoffs (normalization vs performance)\n\nThen: **controlled denormalization** — add back specific denormalized columns with justification for query performance.\n\nOutput: complete normalized schema + migration from current to normalized."),
  ("time-series-data.md","Design a Time-Series Database",["time-series","timescaledb","influxdb","iot"],"advanced","Design a time-series data storage solution for: [DESCRIBE YOUR DATA: IoT sensors / metrics / financial ticks / events].\n\nOption A — TimescaleDB (PostgreSQL extension):\n1. Hypertable setup (auto-partition by time)\n2. Chunk interval (1 hour vs 1 day vs 1 week)\n3. Retention policy (drop data older than N months)\n4. Compression (50-90% storage reduction)\n5. Continuous aggregates (pre-compute hourly/daily summaries)\n6. Time-series queries: time_bucket, lag, interpolation\n\nOption B — InfluxDB:\n7. Measurement, tags, fields design\n8. Flux query language examples\n9. Retention policies\n\nFor my use case: which is better and why?\nBenchmark: expected query latency for 1B rows."),
  ("graph-database.md","Design a Graph Database Schema",["neo4j","graph","database","relationships"],"advanced","Design a graph database schema using Neo4j for: [DESCRIBE YOUR DOMAIN — social network, recommendation engine, dependency graph, fraud detection].\n\n1. **Nodes**: define all node labels and their properties\n2. **Relationships**: define all relationship types and directions\n3. **Properties on relationships**: when to put data on the edge\n4. **Indexes**: node property indexes for lookup\n5. **Constraints**: unique constraints on node properties\n\nCypher queries for your key use cases:\n6. Find all connections within N degrees\n7. Shortest path between two nodes\n8. Recommend based on similar users (collaborative filtering)\n9. Detect cycles (fraud rings)\n10. Pattern matching queries\n\nWhen to use Neo4j vs relational DB — decision matrix."),
  ("database-sharding.md","Design Database Sharding",["sharding","postgresql","scalability","architecture"],"advanced","Design a database sharding strategy for my application at scale.\n\nCurrent situation: [DESCRIBE: single PostgreSQL, projected 100M+ rows, growth rate]\n\nSharding key selection:\n1. User ID sharding: route all user data to same shard\n2. Tenant ID: for multi-tenant SaaS\n3. Date range: for time-series data\n4. Hash-based: even distribution\n\nImplement:\n5. Consistent hashing for shard routing\n6. Application-level sharding (vs Citus)\n7. Cross-shard queries: how to handle joins\n8. Shard rebalancing when adding shards\n9. Hot spots: how to detect and fix\n10. Citus (PostgreSQL extension): managed sharding\n\nAlternative: vertical scaling + read replicas first (defer sharding as long as possible)."),
  ("nosql-selection.md","Choose the Right NoSQL Database",["nosql","dynamodb","mongodb","cassandra"],"advanced","Help me choose the right NoSQL database for: [DESCRIBE YOUR USE CASE, ACCESS PATTERNS, SCALE].\n\nEvaluate:\n1. **MongoDB**: document store, flexible schema, good for catalogs, CMS\n2. **DynamoDB**: AWS managed, single-digit ms at any scale, limited query patterns\n3. **Cassandra**: write-heavy, time-series, geographic distribution\n4. **Redis**: in-memory, caching, real-time, pub/sub\n5. **Elasticsearch**: full-text search, log analytics\n6. **InfluxDB**: time-series metrics\n7. **Neo4j**: graph relationships\n8. **CockroachDB**: distributed SQL (PostgreSQL compatible)\n\nFor my specific access patterns and scale:\n- Winner and justification\n- Data model for the winning DB\n- Failure modes to plan for"),
  ("orm-vs-raw-sql.md","ORM vs Raw SQL Decision Guide",["orm","sql","prisma","postgresql"],"intermediate","Advise on whether to use an ORM or raw SQL for my project.\n\nProject: [DESCRIBE]\nTeam SQL experience: [LOW / MEDIUM / HIGH]\n\nArgumentsfor ORM (Prisma, Drizzle, TypeORM):\n1. Type safety — TypeScript types from schema\n2. Migration management\n3. Relationship loading\n4. Simpler CRUD operations\n5. Less SQL knowledge required\n\nArguments for raw SQL:\n6. Full SQL power (window functions, CTEs, complex queries)\n7. No abstraction overhead\n8. Easier optimization\n9. Better for existing complex schemas\n\nFor MY project specifically:\n- Recommendation with justification\n- If ORM: which one and why\n- Hybrid: ORM for CRUD + raw SQL for complex queries\n- Implementation pattern for the hybrid approach"),
  ("data-warehouse.md","Design a Data Warehouse",["data-warehouse","analytics","dimensional","bigquery"],"advanced","Design a data warehouse for analytics on my application data.\n\nSources: [LIST YOUR OPERATIONAL DATABASES]\nAnalytical questions to answer: [LIST YOUR KEY METRICS]\n\n1. **Star schema design**:\n   - Fact tables: [transactions, events, sessions]\n   - Dimension tables: users, products, dates, locations\n2. **ETL pipeline**: source → transform → load (dbt or Apache Airflow)\n3. **Slowly Changing Dimensions (SCD)**: Type 1 vs Type 2 vs Type 3\n4. **Incremental loading**: only process new/changed records\n5. **Data quality**: validation, deduplication, outlier detection\n6. **Aggregations**: pre-compute summary tables for dashboard\n7. **Platform**: BigQuery vs Snowflake vs Redshift — which and why\n\nExample SQL queries for your key metrics."),
  ("database-replication.md","Set Up Database Replication",["replication","postgresql","high-availability","devops"],"advanced","Set up database replication for high availability and read scaling.\n\nStack: PostgreSQL 15+\n\n1. **Streaming replication** (hot standby):\n   - Primary config: wal_level, max_wal_senders\n   - Replica config: primary_conninfo, hot_standby\n   - Replication slots: don't lose WAL even if replica lags\n   - Monitoring: replication lag\n2. **Read replicas**:\n   - Route read queries to replica\n   - Application-level routing vs PgBouncer vs pgpool\n3. **Failover**:\n   - Detect primary failure (Patroni / pg_auto_failover)\n   - Promote replica to primary\n   - Update connection string (DNS / load balancer)\n   - Recovery time objective: < 30 seconds\n4. **Multi-region**: logical replication across regions\n5. **Testing**: simulate primary failure in staging monthly"),
  ("backup-strategy.md","Design a Database Backup Strategy",["backup","postgresql","disaster-recovery","devops"],"intermediate","Design a comprehensive database backup and recovery strategy.\n\nDatabase: PostgreSQL on [AWS RDS / self-hosted / Supabase]\nData size: [CURRENT SIZE AND GROWTH RATE]\nRTO (recovery time objective): [e.g., < 4 hours]\nRPO (recovery point objective): [e.g., < 1 hour data loss max]\n\nImplement:\n1. **Full backup**: daily, retained 30 days\n2. **WAL archiving**: continuous, enables point-in-time recovery\n3. **Snapshot backup**: hourly for recent windows\n4. **Offsite copies**: 3-2-1 rule (3 copies, 2 media types, 1 offsite)\n5. **Encryption**: encrypt backups at rest\n6. **Restoration testing**: restore to staging weekly, document steps\n7. **Disaster recovery drill**: quarterly full DR exercise\n8. **Monitoring**: alert if backup fails\n\nTool: pgBackRest (better than pg_dump for large databases)."),
  ("multi-tenant-database.md","Design a Multi-Tenant Database",["multi-tenant","saas","postgresql","architecture"],"advanced","Design a multi-tenant database architecture for my SaaS application.\n\nTenants: [EXPECTED NUMBER — dozens? thousands?]\n\nThree approaches:\n\n**Option A — Row-level (shared schema)**:\n- Add `tenant_id` to every table\n- Row Level Security (RLS) to isolate\n- Pros: simple, cheap. Cons: noisy neighbor, harder to export tenant data\n\n**Option B — Schema-per-tenant**:\n- Each tenant gets own PostgreSQL schema\n- Up to ~1000 tenants per DB\n- Pros: easy isolation. Cons: complex migrations\n\n**Option C — Database-per-tenant**:\n- Ultimate isolation\n- Pros: compliance, custom backups. Cons: expensive, complex infra\n\nFor MY tenant count and compliance needs: which approach?\nImplementation for the recommended approach including migration strategy."),
  ("cqrs-event-sourcing.md","Implement CQRS and Event Sourcing",["cqrs","event-sourcing","architecture","postgresql"],"advanced","Implement CQRS and Event Sourcing for: [YOUR DOMAIN].\n\n**Event Sourcing**:\n1. Events table: id, aggregate_type, aggregate_id, event_type, data, created_at\n2. Append-only: never update events\n3. Reconstruct state: replay all events for an aggregate\n4. Snapshot: save state at N events to speed up reconstruction\n5. Event versioning: how to handle schema changes in old events\n\n**CQRS**:\n6. Command side: validate → apply → persist events\n7. Query side: materialized read models (denormalized for query speed)\n8. Projections: event handlers that build read models\n9. Eventual consistency: read side may lag behind write side\n10. Sagas: multi-step processes with compensation\n\nNode.js + PostgreSQL implementation."),
  ("database-design-patterns.md","Database Design Patterns",["patterns","postgresql","design","modeling"],"advanced","Apply these database design patterns to my schema: [DESCRIBE YOUR DOMAIN].\n\n1. **Polymorphic associations**: entity belongs to multiple parent types\n2. **EAV (Entity-Attribute-Value)**: flexible attributes (use sparingly)\n3. **Adjacency list**: self-referential (parent_id) for trees\n4. **Nested sets**: faster tree traversal, harder updates\n5. **Closure table**: best tree reads + writes\n6. **Soft delete**: deleted_at timestamp (and how to index correctly)\n7. **Audit log**: who changed what and when (shadow table pattern)\n8. **Optimistic locking**: version column for concurrent update detection\n9. **UUID vs integer primary keys**: tradeoffs\n10. **Composite primary keys**: when to use, when to avoid\n11. **Bridge table**: many-to-many with extra attributes\n12. **Materialized path**: store full path as string for hierarchy"),
  ("sql-window-functions.md","Master SQL Window Functions",["sql","window-functions","postgresql","analytics"],"intermediate","Master SQL window functions for analytics queries.\n\nMy data: [DESCRIBE YOUR TABLES]\nAnalytics questions: [WHAT DO YOU NEED TO CALCULATE]\n\nTeach me with my data:\n1. **ROW_NUMBER()**: assign unique row numbers within partition\n2. **RANK() / DENSE_RANK()**: rankings with ties\n3. **NTILE(n)**: divide rows into N buckets\n4. **LAG() / LEAD()**: access previous/next row value\n5. **FIRST_VALUE() / LAST_VALUE()**: first/last value in window\n6. **SUM() / AVG() / COUNT()**: running totals and rolling averages\n7. **PARTITION BY**: reset window per group\n8. **ROWS BETWEEN**: define frame: current row, N preceding, unbounded\n\nFor each: SQL query against my data + result explanation."),
  ("database-encryption.md","Implement Database Encryption",["encryption","security","postgresql","compliance"],"advanced","Implement encryption for sensitive data in my database.\n\nSensitive fields: [LIST: SSN, credit cards, health data, etc.]\nCompliance: [HIPAA / PCI-DSS / GDPR]\n\nLayers:\n1. **Encryption at rest**: disk-level (transparent, OS/DB handles)\n2. **Encryption in transit**: SSL/TLS for DB connections (verify, don't just encrypt)\n3. **Column-level encryption**: pgcrypto for specific sensitive fields\n4. **Application-level encryption**: encrypt before insert, decrypt on read\n5. **Key management**: AWS KMS / HashiCorp Vault (don't store keys in DB)\n6. **Searchable encryption**: how to search encrypted fields\n7. **Tokenization**: replace sensitive data with non-sensitive token\n8. **Data masking**: return masked value to non-privileged users\n\nFor each compliance framework: what is required vs nice-to-have."),
  ("database-connection-management.md","Manage Database Connections in Production",["connections","postgresql","pooling","performance"],"advanced","Optimize database connection management for production.\n\nStack: Node.js + PostgreSQL\nLoad: [EXPECTED RPS AND CONCURRENCY]\n\n1. **Connection pool sizing**: (CPU cores × 2) + 1 per server\n2. **pg pool config**: max, min, idleTimeoutMillis, connectionTimeoutMillis\n3. **PgBouncer**: transaction pooling for serverless/high concurrency\n4. **Connection leaks**: detect and fix (log long-held connections)\n5. **Serverless problem**: functions create new connections per invocation\n6. **RDS Proxy**: managed connection pooler for AWS\n7. **Monitoring**: pg_stat_activity, wait events, max_connections\n8. **Connection limits per role**: `ALTER ROLE myuser CONNECTION LIMIT 100`\n9. **Graceful shutdown**: drain connections before restart\n10. **Circuit breaker**: stop making new connections if DB is overwhelmed"),
  ("stored-procedures.md","Write Effective Stored Procedures",["stored-procedures","postgresql","plpgsql","backend"],"advanced","Write stored procedures and functions for these complex operations: [DESCRIBE YOUR OPERATIONS].\n\nUsing: PostgreSQL PL/pgSQL\n\n1. **Functions vs procedures**: when to use each\n2. **SECURITY DEFINER**: run as function owner (for RLS bypass where needed)\n3. **Transaction control**: COMMIT/ROLLBACK within procedure\n4. **Exception handling**: EXCEPTION block, SQLSTATE codes\n5. **Dynamic SQL**: EXECUTE for dynamic queries\n6. **Loops and cursors**: FOR loops, cursor fetch\n7. **Returning data**: SETOF, TABLE, record types\n8. **Triggers**: BEFORE/AFTER, ROW/STATEMENT level\n9. **Performance**: inlining optimization, search_path\n10. **Testing**: pgTAP for PL/pgSQL unit tests\n\nAlternative: should this logic be in the application layer?"),
  ("database-monitoring.md","Monitor Your Database",["monitoring","postgresql","metrics","alerting"],"advanced","Set up comprehensive database monitoring.\n\nDatabase: PostgreSQL (self-hosted or AWS RDS)\n\nKey metrics:\n1. **Connection count**: vs max_connections (alert at 80%)\n2. **Query latency**: p95, p99 per query type\n3. **Cache hit rate**: buffer cache hit should be > 99%\n4. **Vacuum status**: tables needing vacuum, bloat\n5. **Replication lag**: streaming + logical replication lag\n6. **Lock waits**: long-running locks blocking queries\n7. **Deadlocks**: frequency and which queries cause them\n8. **Index usage**: unused indexes wasting space + write overhead\n9. **Table/index bloat**: dead rows percentage\n10. **Disk I/O**: read vs write, iops, wait time\n\nTools: pg_stat_statements, pg_activity, pgBadger log analyzer, Prometheus pg_exporter."),
  ("data-modeling-ecommerce.md","Data Model an E-Commerce System",["ecommerce","data-modeling","postgresql","schema"],"intermediate","Design the complete data model for an e-commerce system.\n\nRequirements:\n- Products with variants (size, color, material combinations)\n- Inventory tracking per variant per warehouse\n- Orders with line items, taxes, discounts, shipping\n- Customer management with addresses\n- Pricing: MSRP, sale price, customer-tier pricing\n- Reviews and ratings\n- Category hierarchy (unlimited depth)\n\nOutput:\n1. Complete ER diagram (Mermaid)\n2. CREATE TABLE SQL (PostgreSQL)\n3. Key indexes\n4. Sample queries for: product listing with price, order total, inventory check\n5. The 3 hardest modeling decisions and why you chose as you did"),
  ("analytical-queries.md","Write Complex Analytical SQL",["sql","analytics","postgresql","reporting"],"advanced","Write complex analytical SQL queries for my business intelligence needs.\n\nSchema: [PASTE YOUR SCHEMA]\nQuestions to answer:\n1. [BUSINESS QUESTION 1]\n2. [BUSINESS QUESTION 2]\n3. [BUSINESS QUESTION 3]\n\nFor each query:\n1. SQL with full explanation of each clause\n2. EXPLAIN ANALYZE analysis\n3. Index recommendations to optimize it\n4. Alternative approaches compared\n\nConcepts to use where appropriate:\n- CTEs and recursive CTEs\n- Window functions\n- ROLLUP and CUBE for multi-dimensional aggregation\n- LATERAL joins\n- JSON aggregation\n- Conditional aggregation (SUM CASE WHEN)\n- Materialized views for frequently-run queries"),
  ("database-access-control.md","Implement Database Access Control",["security","postgresql","rbac","access-control"],"advanced","Implement principle-of-least-privilege access control for my PostgreSQL database.\n\nRoles needed: [e.g., API service, analytics, admin, migration runner]\n\nImplement:\n1. **Roles hierarchy**: base roles inherited by specific roles\n2. **GRANT syntax**: table-level, column-level, row-level\n3. **Row Level Security (RLS)**: policies per role per table\n4. **Schema permissions**: USAGE, CREATE\n5. **Function SECURITY DEFINER**: run elevated for specific operations\n6. **Connection limits per role**\n7. **Audit logging**: log every query from admin role\n8. **Network restriction**: pg_hba.conf IP allowlist per role\n9. **Password rotation**: procedure without downtime\n10. **Application user**: never connect as postgres superuser\n\nOutput: complete role setup SQL + documentation."),
  ("database-design-review.md","Review a Database Schema",["schema","review","postgresql","design"],"intermediate","Review this database schema and identify all issues:\n\n[PASTE YOUR SCHEMA]\n\nAnalyze:\n1. **Normalization**: identify violations and how to fix them\n2. **Data types**: wrong types (e.g., storing numbers as VARCHAR)\n3. **Missing constraints**: NOT NULL, UNIQUE, CHECK, FK\n4. **Missing indexes**: obvious lookup columns without index\n5. **Naming**: inconsistent conventions\n6. **Performance**: potential N+1, missing composite indexes\n7. **Security**: sensitive data without encryption markers\n8. **Scalability**: design issues that won't scale to 10x data\n9. **Redundancy**: data stored in multiple places\n10. **Audit trail**: missing created_at/updated_at\n\nFor each issue: severity + explanation + SQL to fix."),
  ("database-schema-generation.md","Generate a Database Schema from Requirements",["schema","postgresql","requirements","design"],"intermediate","Generate a database schema from these business requirements:\n\n[PASTE YOUR BUSINESS REQUIREMENTS DOCUMENT]\n\nProcess:\n1. **Noun extraction**: identify entities from requirements\n2. **Relationship identification**: one-to-many, many-to-many\n3. **Attribute mapping**: business terms → database columns + types\n4. **Business rules → constraints**: required fields, valid values, uniqueness\n5. **Decisions log**: document every non-obvious choice\n\nOutput:\n- Mermaid ER diagram\n- PostgreSQL CREATE TABLE statements (production-quality)\n- Indexes\n- Sample seed data\n- List of assumptions made (for stakeholder review)"),
  ("postgresql-jsonb.md","Master PostgreSQL JSONB",["postgresql","jsonb","nosql","querying"],"advanced","Master JSONB in PostgreSQL for flexible schema storage.\n\nMy use case: [DESCRIBE WHAT YOU'RE STORING AS JSON]\n\n1. **JSONB vs JSON**: always use JSONB (binary, indexed)\n2. **Operators**: `->`, `->>`, `#>`, `#>>`, `@>`, `<@`, `?`, `?|`, `?&`\n3. **Indexing**: GIN index (full doc), jsonb_path_ops for `@>`, expression index for specific keys\n4. **Functions**: jsonb_set, jsonb_insert, jsonb_strip_nulls, jsonb_object_keys\n5. **Path operations**: jsonb_path_query (JSONPath)\n6. **Aggregation**: jsonb_agg, jsonb_object_agg\n7. **Schema validation**: CHECK constraint with custom function\n8. **Updating nested keys**: jsonb_set deep update\n9. **Performance**: when JSONB is fast and when it slows you down\n10. **Migration pattern**: relational → JSONB → relational again\n\nFor each: working SQL examples with my use case."),
  ("soft-delete-pattern.md","Implement Soft Delete",["soft-delete","postgresql","patterns","data"],"beginner","Implement soft delete for my application.\n\nTables to soft-delete: [LIST]\n\nImplement:\n1. Add `deleted_at TIMESTAMPTZ NULL` to each table\n2. PostgreSQL views: `active_users` that filters `WHERE deleted_at IS NULL`\n3. RLS policy: automatically filter deleted rows for the API user role\n4. Cascade soft deletes: when user is deleted, soft-delete their posts/comments too\n5. Restore: undelete functionality (admin only)\n6. Hard delete schedule: permanently delete soft-deleted records after 90 days (GDPR)\n7. Indexes: partial index `WHERE deleted_at IS NULL` for performance\n8. Application layer: always query through the view (prevent bugs)\n9. Audit trail: who deleted what and when\n10. Find deleted records: admin query to see deleted items"),
  ("database-seeds.md","Generate Realistic Database Seed Data",["seed","testing","faker","postgresql"],"beginner","Generate realistic seed data for my database.\n\nSchema: [PASTE YOUR SCHEMA]\n\nRequirements:\n- [N] users with diverse realistic names (international)\n- [N] records for each main entity\n- Realistic relationships (users have 1-5 posts, etc.)\n- Edge cases: empty strings where nullable, max length strings, special characters\n- Different status distributions: 80% active, 15% inactive, 5% suspended\n\nOutput:\n1. SQL INSERT statements for base seed data\n2. Node.js script using Faker.js for generating larger datasets\n3. Python script alternative\n4. Specific edge case records to always include in seeds\n5. Instructions for: fresh seed (delete + reseed) vs additive seed\n6. CI seed: fast minimal seed for test suite"),
  ("database-documentation.md","Document Your Database Schema",["documentation","schema","postgresql","data-dictionary"],"beginner","Generate comprehensive documentation for my database schema.\n\nSchema: [PASTE YOUR SCHEMA]\n\nDocument:\n1. **Data dictionary**: every table and column with:\n   - Purpose of the table\n   - Each column: data type, constraints, description, example value\n   - Relationships to other tables\n2. **ER diagram** (Mermaid)\n3. **Query patterns**: common queries and how to run them\n4. **Access patterns**: which queries run most frequently\n5. **Index documentation**: what each index is for\n6. **Stored procedures/triggers**: what they do and when\n7. **Naming conventions**: document the conventions used\n8. **Change log**: schema change history\n\nOutput in Markdown format, suitable for a team wiki."),
  ("postgres-performance-tuning.md","Tune PostgreSQL for Production",["postgresql","performance","configuration","devops"],"advanced","Tune PostgreSQL configuration for production performance.\n\nServer specs: [CPU cores, RAM, disk type (SSD/NVMe), workload type (OLTP/OLAP/mixed)]\n\nConfigure postgresql.conf:\n1. **Memory**: shared_buffers (25% RAM), effective_cache_size (75% RAM), work_mem, maintenance_work_mem\n2. **WAL**: wal_buffers, checkpoint_completion_target, max_wal_size\n3. **Connections**: max_connections, connection pooler recommendation\n4. **Planner**: random_page_cost (1.1 for SSD vs 4 for HDD), effective_io_concurrency\n5. **Autovacuum**: tuning for high-write tables\n6. **Logging**: log_min_duration_statement = 1000 (log slow queries)\n7. **Parallelism**: max_parallel_workers_per_gather\n\nOutput: complete postgresql.conf with explanations for each setting."),
  ("database-transactions.md","Master Database Transactions",["transactions","postgresql","acid","concurrency"],"advanced","Master transactions and concurrency control in PostgreSQL.\n\nMy use case: [DESCRIBE CONCURRENT OPERATIONS]\n\n1. **ACID properties**: what each means in practice with examples\n2. **Isolation levels**:\n   - READ COMMITTED (default): what can go wrong\n   - REPEATABLE READ: solves phantom reads\n   - SERIALIZABLE: highest isolation, performance cost\n3. **Phenomena**: dirty read, non-repeatable read, phantom read, serialization anomaly\n4. **Optimistic locking**: version column + WHERE version = N\n5. **Pessimistic locking**: SELECT FOR UPDATE, SKIP LOCKED\n6. **SKIP LOCKED**: job queue pattern\n7. **Deadlocks**: how to detect, how to prevent (consistent lock ordering)\n8. **Long transactions**: why they're dangerous, how to avoid\n9. **Advisory locks**: application-level locks in PostgreSQL\n10. **Two-phase commit**: distributed transactions"),
  ("database-scaling.md","Scale Your Database",["scaling","postgresql","read-replicas","sharding"],"advanced","Create a database scaling plan for my application.\n\nCurrent: [SINGLE DB, SIZE, QUERIES/SEC]\nProjected: [10x / 100x GROWTH over N months]\n\nScaling ladder (do these in order):\n1. **Optimize queries and indexes** (free, do first)\n2. **Vertical scaling**: bigger instance (quick fix, but has ceiling)\n3. **Connection pooling**: PgBouncer (handle more concurrent connections)\n4. **Read replicas**: route reads to replica (helps 80% of workloads)\n5. **Caching layer**: Redis for hot data (reduce DB load 50-90%)\n6. **Partitioning**: split large tables (time-based or range)\n7. **Horizontal sharding**: Citus or app-level sharding (last resort)\n8. **CQRS**: separate read and write models\n\nFor each step: when to do it (trigger metric) + implementation time."),
]

for filename, title, tags, difficulty, prompt_text in db_design:
    write(cat / filename, make_prompt("database-design", title, tags, difficulty, prompt_text))

# ─── CATEGORY 07: DEVOPS & CI/CD ───────────────────────────────────────────────
cat = PROMPTS / "07-devops-cicd"
devops = [
  ("github-actions.md","Write a Complete GitHub Actions CI/CD Pipeline",["github-actions","ci-cd","devops","automation"],"intermediate","Write a complete GitHub Actions CI/CD pipeline for my [Node.js / Python / Go] project.\n\nWorkflows to create:\n\n**CI workflow** (on every PR):\n1. Checkout code\n2. Setup Node/Python/Go with version caching\n3. Install dependencies (with cache)\n4. Lint (ESLint, Ruff, golint)\n5. Type check (TypeScript tsc, mypy)\n6. Unit tests (with coverage report)\n7. Integration tests (spin up Docker services)\n8. Build (verify it compiles)\n9. Security scan (CodeQL or Snyk)\n10. Post results as PR comment\n\n**CD workflow** (on merge to main):\n11. Build Docker image\n12. Push to registry (GHCR)\n13. Deploy to staging (Fly.io / Railway / AWS ECS)\n14. Run smoke tests\n15. Deploy to production (manual approval gate)\n\nOutput: complete YAML workflow files."),
  ("docker-compose.md","Create Docker Compose for Development",["docker","docker-compose","local-dev","containers"],"intermediate","Create a complete Docker Compose setup for local development of my app.\n\nServices:\n- App: [Node.js / Python / Go]\n- Database: PostgreSQL 16\n- Cache: Redis 7\n- [OTHER SERVICES: Elasticsearch, MinIO, Mailhog, etc.]\n\n`docker-compose.yml`:\n1. Each service with health checks\n2. Volume mounts for hot reload (don't copy code into container)\n3. Named volumes for persistent data (DB data survives container restart)\n4. Environment variables from `.env` file\n5. Networking (internal DNS between services)\n6. `depends_on` with health check conditions\n7. Resource limits (prevent one service from hogging all RAM)\n\nAlso:\n- `docker-compose.override.yml` for dev-specific overrides\n- `docker-compose.prod.yml` for production-like settings\n- Makefile with: `make up`, `make down`, `make logs`, `make shell`"),
  ("kubernetes-deployment.md","Deploy to Kubernetes",["kubernetes","k8s","deployment","helm"],"advanced","Write Kubernetes manifests to deploy my application.\n\nApp: [DESCRIBE YOUR APP: what containers, what dependencies]\n\nManifests to create:\n1. **Namespace**: isolate resources\n2. **Deployment**: replicas, container spec, resource requests/limits, liveness/readiness probes\n3. **Service**: ClusterIP for internal, LoadBalancer or NodePort for external\n4. **Ingress**: route traffic with Nginx ingress controller\n5. **ConfigMap**: non-sensitive config\n6. **Secret**: sensitive values (base64 encoded, or External Secrets Operator)\n7. **HorizontalPodAutoscaler**: scale on CPU or custom metrics\n8. **PodDisruptionBudget**: ensure at least N pods always available\n9. **ServiceAccount**: least-privilege RBAC\n10. **NetworkPolicy**: restrict pod-to-pod traffic\n\nAlso: `kubectl apply` order and health check commands."),
  ("terraform-aws.md","Infrastructure as Code with Terraform",["terraform","aws","iac","devops"],"advanced","Write Terraform code for my AWS infrastructure.\n\nInfrastructure to provision:\n- [LIST YOUR RESOURCES: VPC, EC2, RDS, S3, CloudFront, ALB, etc.]\n\nBest practices to follow:\n1. **State management**: S3 backend + DynamoDB lock table\n2. **Modules**: one module per logical group (networking, database, app)\n3. **Variables**: with type, description, validation\n4. **Locals**: computed values\n5. **Outputs**: export values to other modules\n6. **Data sources**: reference existing AWS resources\n7. **Workspaces** or **separate state**: staging vs production\n8. **Secrets**: never hardcode — use AWS Secrets Manager\n9. **Tagging**: consistent tags on all resources\n10. **Destroy protection**: `prevent_destroy = true` on critical resources\n\nOutput: complete, working Terraform code with modules."),
  ("aws-ecs-deployment.md","Deploy with AWS ECS and Fargate",["aws","ecs","fargate","containers"],"advanced","Set up complete deployment to AWS ECS Fargate.\n\nApp: [DESCRIBE YOUR CONTAINERIZED APP]\n\nInfrastructure (using Terraform):\n1. VPC with public/private subnets (2 AZs)\n2. Application Load Balancer in public subnets\n3. ECS Cluster\n4. ECS Task Definition: container spec, CPU/memory, env vars from Secrets Manager\n5. ECS Service: desired count, deployment config (rolling update)\n6. Auto Scaling: scale on CPU > 70%\n7. Security Groups: ALB → ECS only, ECS → RDS only\n8. IAM Role for task: least privilege\n9. CloudWatch logs\n10. ECR repository for Docker images\n\nCI/CD:\n- GitHub Actions: build → push to ECR → update ECS service\n- Blue/green deployment using CodeDeploy"),
  ("monitoring-setup.md","Set Up Production Monitoring Stack",["monitoring","prometheus","grafana","alerting"],"advanced","Set up a complete production monitoring stack.\n\nStack: Prometheus + Grafana + Alertmanager\n\nUsing Docker Compose:\n1. **Prometheus**: scrape config for your services + node exporter\n2. **Grafana**: pre-configured datasource, provisioned dashboards\n3. **Alertmanager**: route alerts to Slack/PagerDuty\n4. **Node Exporter**: host-level metrics (CPU, memory, disk, network)\n5. **cAdvisor**: Docker container metrics\n6. **Blackbox Exporter**: HTTP endpoint monitoring (uptime)\n7. **Application metrics**: your app exposes /metrics (Prometheus format)\n\nDashboards to create:\n- System health (CPU, memory, disk)\n- Application (request rate, error rate, latency)\n- Business metrics (signups, revenue, active users)\n\nAlerts: list the 10 most important alerts with thresholds."),
  ("nginx-config.md","Write Production Nginx Configuration",["nginx","web-server","reverse-proxy","ssl"],"intermediate","Write a production-ready Nginx configuration for my app.\n\nSetup:\n- Nginx as reverse proxy in front of [Node.js / Python / other] app\n- SSL/TLS with Let's Encrypt\n- Multiple domains: [LIST YOUR DOMAINS]\n\nConfiguration:\n1. HTTPS redirect (HTTP → HTTPS)\n2. TLS 1.2 / 1.3 only, strong cipher suites\n3. HSTS header with preload\n4. Security headers (see OWASP recommendations)\n5. Gzip compression for text assets\n6. Proxy to upstream with timeouts\n7. WebSocket support (Upgrade/Connection headers)\n8. Rate limiting: limit_req_zone\n9. Static file serving with long cache headers\n10. Health check endpoint passthrough\n11. Access log format (structured for log analysis)\n12. Worker processes = auto, worker_connections = 1024"),
  ("cicd-best-practices.md","CI/CD Best Practices for Production",["ci-cd","devops","best-practices","pipelines"],"intermediate","Implement CI/CD best practices for my team's deployment pipeline.\n\nCurrent setup: [DESCRIBE YOUR CURRENT CI/CD SITUATION]\n\nBest practices to implement:\n1. **Fail fast**: run fastest checks first (lint before tests)\n2. **Parallelism**: run independent jobs in parallel\n3. **Caching**: dependency cache, Docker layer cache\n4. **Artifact storage**: pass build artifacts between jobs\n5. **Environment parity**: staging = production config\n6. **Rollback**: one-click rollback to previous version\n7. **Feature flags**: deploy code without enabling feature\n8. **Canary deployment**: route 1% traffic to new version first\n9. **Smoke tests**: post-deploy verification\n10. **Secrets rotation**: no long-lived secrets\n11. **Dependency updates**: Dependabot or Renovate bot\n12. **DORA metrics**: track deployment frequency, lead time, MTTR, change failure rate"),
  ("docker-security.md","Harden Docker Containers for Production",["docker","security","containers","devops"],"advanced","Harden my Docker containers for production security.\n\nCurrent Dockerfile: [PASTE OR DESCRIBE]\n\nSecurity improvements:\n1. **Non-root user**: run process as non-root inside container\n2. **Read-only filesystem**: `--read-only`, writable mounts only where needed\n3. **Minimal base image**: distroless or alpine (reduce attack surface)\n4. **Multi-stage build**: no build tools in final image\n5. **No secrets in image**: use runtime env vars or secrets manager\n6. **Pinned versions**: specific tags, not `latest`\n7. **Layer ordering**: cache dependencies layer separately from code\n8. **Image scanning**: Trivy or Snyk in CI pipeline\n9. **COPY vs ADD**: use COPY, never ADD\n10. **HEALTHCHECK**: define health check in Dockerfile\n11. **Capabilities**: drop all, add back only what's needed\n12. `.dockerignore`: exclude .git, .env, node_modules"),
  ("helm-chart.md","Create a Helm Chart for Kubernetes",["helm","kubernetes","charts","devops"],"advanced","Create a Helm chart for deploying my application to Kubernetes.\n\nApp: [DESCRIBE YOUR APPLICATION]\n\nChart structure:\n```\nmychart/\n  Chart.yaml\n  values.yaml\n  templates/\n    deployment.yaml\n    service.yaml\n    ingress.yaml\n    configmap.yaml\n    secret.yaml\n    hpa.yaml\n    pdb.yaml\n    _helpers.tpl\n```\n\nValues to parameterize:\n- Image repo and tag\n- Replica count\n- Resource limits\n- Ingress host and TLS\n- Environment variables\n- Secrets (from external secrets operator)\n- Enable/disable optional components\n\nInclude: `Chart.yaml`, complete `values.yaml` with comments, and all templates."),
  ("cloudflare-workers.md","Deploy with Cloudflare Workers",["cloudflare","workers","edge","deployment"],"intermediate","Deploy my application to Cloudflare Workers (edge computing).\n\nApp type: [API / static site / SSR / proxy]\n\nImplement:\n1. **Worker script** in TypeScript using Hono framework\n2. **KV storage**: for caching, session state, feature flags\n3. **D1 database**: SQLite at the edge for small datasets\n4. **R2 storage**: S3-compatible object storage\n5. **Durable Objects**: stateful edge (real-time collaboration, rate limiting)\n6. **Queue**: Cloudflare Queues for background processing\n7. **Cron triggers**: scheduled jobs\n8. **Wrangler config**: `wrangler.toml` with environments\n9. **CI/CD**: GitHub Actions → `wrangler deploy`\n10. **Custom domain**: bind to your domain with Cloudflare DNS"),
  ("load-balancing.md","Configure Load Balancing",["load-balancing","nginx","haproxy","architecture"],"advanced","Set up load balancing for my application.\n\nArchitecture: [N app servers, what protocol, session requirements]\n\nOptions to evaluate:\n\n**Nginx upstream**:\n- round_robin (default)\n- least_conn\n- ip_hash (sticky sessions)\n- weight distribution\n\n**HAProxy** (more features):\n- ACL-based routing\n- Health checks (active and passive)\n- SSL termination\n- Connection rate limiting\n- Stats page\n\n**AWS ALB**:\n- Target groups + rules\n- Path-based routing\n- Weighted routing (canary)\n- Sticky sessions\n\nFor MY setup: which to use and why.\nOutput: complete config + health check setup."),
  ("blue-green-deployment.md","Implement Blue-Green Deployment",["blue-green","deployment","zero-downtime","devops"],"advanced","Implement blue-green deployment for zero-downtime releases.\n\nCurrent setup: [DESCRIBE YOUR DEPLOYMENT INFRASTRUCTURE]\n\nBlue-green strategy:\n1. Blue: current production version (100% traffic)\n2. Green: new version (deployed but no traffic)\n3. Smoke test green environment\n4. Switch traffic: blue → green (instant or gradual)\n5. Keep blue running for 30 minutes (rollback window)\n6. Tear down blue\n\nImplementation options:\n- **AWS ECS**: blue/green with CodeDeploy\n- **Kubernetes**: two Deployments, update Service selector\n- **Nginx**: upstream groups, reload config without downtime\n- **Feature flags**: code-level blue/green\n\nFor MY stack: complete implementation with rollback procedure."),
  ("secret-management.md","Manage Secrets in Production",["secrets","security","vault","aws-secrets-manager"],"advanced","Set up secure secrets management for my production environment.\n\nSecrets to manage: [LIST TYPES: DB passwords, API keys, JWT secrets, etc.]\n\nOptions:\n**AWS Secrets Manager**:\n1. Store secrets with automatic rotation\n2. IAM policy: EC2/ECS can read specific secrets\n3. SDK integration (Node.js, Python)\n4. Rotation lambda for database passwords\n\n**HashiCorp Vault**:\n5. Dynamic secrets: Vault generates short-lived DB credentials\n6. App role authentication\n7. Kubernetes integration (vault-agent-injector)\n\n**GitHub Actions**:\n8. Environment secrets for CI/CD\n9. OIDC federation: GitHub → AWS without long-lived keys\n\nNever again:\n- Hardcode secrets in code\n- Store secrets in environment files committed to git\n- Share secrets via Slack/email"),
  ("log-aggregation.md","Set Up Centralized Log Aggregation",["logging","elk","grafana-loki","devops"],"advanced","Set up centralized log aggregation for my distributed application.\n\nLogs to aggregate from: [LIST SERVICES]\n\nOption A — ELK Stack (self-hosted):\n1. Elasticsearch: store and index logs\n2. Logstash: parse and transform\n3. Kibana: visualize and search\n4. Filebeat / Fluentd: ship logs from each service\n5. Index lifecycle policy: hot → warm → cold → delete\n\nOption B — Grafana Loki (cheaper):\n6. Loki: log aggregation without full-text indexing\n7. Promtail: log shipper\n8. Grafana: query with LogQL\n9. Cost: 10x cheaper than ELK for most use cases\n\nFor both:\n- Structured JSON logging from applications\n- Log retention and archiving policy\n- Alerting on error patterns"),
  ("infrastructure-cost.md","Optimize Cloud Infrastructure Costs",["cost-optimization","aws","cloud","finops"],"advanced","Optimize my cloud infrastructure costs.\n\nCurrent spend: [DESCRIBE YOUR CURRENT CLOUD SPEND AND RESOURCES]\n\nOptimization strategies:\n1. **Right-sizing**: identify over-provisioned instances (CloudWatch metrics)\n2. **Reserved instances / savings plans**: 30-70% discount for committed usage\n3. **Spot instances**: 70-90% discount for non-critical workloads\n4. **Auto-scaling**: don't run at peak capacity 24/7\n5. **S3 lifecycle policies**: move old data to Glacier\n6. **NAT Gateway**: expensive, minimize traffic through it\n7. **Data transfer**: avoid cross-region and cross-AZ transfers\n8. **RDS**: stop non-production databases on nights/weekends\n9. **Unused resources**: find and delete orphaned volumes, old snapshots\n10. **CloudWatch metrics**: which metrics you're paying for vs actually using\n\nTarget: 30% cost reduction. Show the calculation."),
  ("disaster-recovery.md","Design a Disaster Recovery Plan",["disaster-recovery","rto","rpo","architecture"],"advanced","Design a disaster recovery plan for my application.\n\nApplication: [DESCRIBE]\nRTO (Recovery Time Objective): [e.g., < 4 hours]\nRPO (Recovery Point Objective): [e.g., < 1 hour]\n\nFailure scenarios to plan for:\n1. Database failure → automated failover to replica\n2. Single AZ outage → multi-AZ deployment\n3. Entire region outage → multi-region failover\n4. Application bug in production → rollback procedure\n5. Data corruption → point-in-time restore\n6. DDoS attack → rate limiting + CDN + WAF\n7. Third-party API failure → circuit breaker + fallback\n8. Developer error → change management, peer review gates\n\nFor each:\n- Prevention measures\n- Detection (how to know it happened)\n- Response playbook (step by step)\n- Recovery time estimate"),
  ("container-registry.md","Set Up a Container Registry",["docker","registry","ghcr","ecr"],"intermediate","Set up a container registry and image management workflow.\n\nRegistry options:\n- **GitHub Container Registry (GHCR)**: free for public, free private with GitHub Team\n- **AWS ECR**: pay-per-storage, no egress if in same region as ECS\n- **Docker Hub**: easy, limited free tier\n- **Artifact Registry (GCP)**: if using GCP\n\nFor MY choice:\n1. Registry setup and authentication\n2. Push workflow from GitHub Actions\n3. Image tagging strategy: `latest`, git SHA, semantic version\n4. Multi-architecture builds (linux/amd64 + linux/arm64)\n5. Image scanning for vulnerabilities (before pushing)\n6. Retention policy: keep last 10 images, delete older\n7. Pull secrets in Kubernetes\n8. Rate limiting considerations"),
  ("ansible-playbook.md","Write Ansible Playbooks for Server Config",["ansible","configuration-management","devops","linux"],"advanced","Write Ansible playbooks to configure and manage my servers.\n\nServers: [DESCRIBE: Ubuntu 22.04, what services run on them]\n\nPlaybooks to write:\n1. **base.yml**: system updates, timezone, NTP, swap, kernel params\n2. **security.yml**: UFW firewall, fail2ban, SSH hardening (no root, no password auth)\n3. **docker.yml**: install Docker + Docker Compose, manage with systemd\n4. **nginx.yml**: install, configure, SSL with Certbot, test config\n5. **app.yml**: deploy application, environment config, systemd service\n6. **monitoring.yml**: install node exporter, configure log shipping\n7. **backup.yml**: configure database backup cron job\n\nInventory: staging and production groups\nVault: encrypt sensitive values\nIdempotent: safe to run multiple times"),
  ("ssl-tls-setup.md","Set Up SSL/TLS Correctly",["ssl","tls","https","certbot"],"intermediate","Set up SSL/TLS correctly for my web application.\n\nSetup: Nginx + Let's Encrypt (Certbot)\n\n1. **Certbot installation and certificate issuance** (webroot or DNS challenge)\n2. **Auto-renewal**: cron job + Nginx reload hook\n3. **TLS configuration**:\n   - Minimum TLS 1.2 (drop TLS 1.0/1.1)\n   - Strong cipher suites (ECDHE + AES-GCM)\n   - Perfect Forward Secrecy\n   - Diffie-Hellman params (4096-bit)\n4. **HSTS**: Strict-Transport-Security header with preload\n5. **OCSP stapling**: reduce latency on handshake\n6. **HTTP/2**: enable for performance\n7. **Testing**: SSL Labs A+ rating target\n8. **Wildcard certificate**: if needed for subdomains\n9. **Certificate monitoring**: alert 30 days before expiry\n10. **CAA DNS record**: restrict certificate issuance to Let's Encrypt"),
  ("deployment-checklist.md","Production Deployment Checklist",["deployment","checklist","devops","production"],"intermediate","Create a comprehensive production deployment checklist.\n\nMy app: [DESCRIBE YOUR STACK AND INFRASTRUCTURE]\n\n**Pre-deployment**:\n□ All tests passing (unit, integration, E2E)\n□ Security scan passed (Snyk / npm audit)\n□ Performance regression test passed\n□ Database migrations tested on staging with production data copy\n□ Feature flags set correctly for rollout plan\n□ Rollback plan documented and tested\n□ On-call engineer aware and available\n□ Stakeholders notified (if user-visible change)\n\n**During deployment**:\n□ Deploy to staging first\n□ Smoke test staging\n□ Monitor error rates during rollout\n□ Deploy to production (blue/green or rolling)\n□ Watch dashboards for 15 minutes\n\n**Post-deployment**:\n□ Smoke test production\n□ Alert the team\n□ Update changelog\n□ Close the deployment issue/PR"),
  ("cicd-security.md","Secure Your CI/CD Pipeline",["security","ci-cd","supply-chain","devops"],"advanced","Harden my CI/CD pipeline against supply chain attacks.\n\nCurrent pipeline: GitHub Actions\n\nThreats:\n1. Compromised dependencies (supply chain attack)\n2. Stolen secrets from CI logs\n3. Untrusted code in pull requests\n4. Malicious GitHub Actions\n\nHardening:\n1. **Pin action versions**: use SHA hash, not tags\n2. **Minimal permissions**: `permissions: read-all` by default, grant write only where needed\n3. **OIDC for cloud auth**: no long-lived AWS/GCP credentials\n4. **Secret masking**: secrets never in logs\n5. **Dependency lock files**: commit package-lock.json, poetry.lock\n6. **Verify downloads**: checksum verification for any downloaded tools\n7. **Code signing**: sign your container images (cosign)\n8. **SBOM generation**: Software Bill of Materials on every build\n9. **OpenSSF Scorecard**: measure and improve supply chain security\n10. **Third-party action audit**: review all actions in use"),
  ("fly-io-deployment.md","Deploy to Fly.io",["fly-io","deployment","containers","devops"],"beginner","Deploy my application to Fly.io.\n\nApp: [DESCRIBE: what it is, what port it listens on, any databases/redis needed]\n\n1. **fly.toml**: complete config file\n   - app name, region selection\n   - HTTP service with internal port\n   - health check configuration\n   - environment variables\n   - volume mounts for persistent data\n2. **Dockerfile**: optimized for Fly.io\n3. **PostgreSQL**: provision Fly Postgres cluster\n4. **Redis**: Upstash Redis integration\n5. **Secrets**: `fly secrets set KEY=VALUE`\n6. **Scaling**: `fly scale count 2` for zero-downtime deploys\n7. **GitHub Actions**: auto-deploy on push to main\n8. **Custom domain**: add and configure SSL\n9. **Monitoring**: Fly metrics integration\n10. **Connecting locally**: fly proxy for local DB access"),
  ("railway-deployment.md","Deploy to Railway",["railway","deployment","devops","beginner"],"beginner","Deploy my full-stack app to Railway.\n\nApp: [DESCRIBE: frontend, backend, database]\n\nStep-by-step:\n1. `railway init` and `railway link` for existing project\n2. **Environment variables**: set via dashboard or CLI\n3. **PostgreSQL plugin**: provision and link to your app (DATABASE_URL auto-set)\n4. **Redis plugin**: add for caching/queues\n5. **Build command**: override if not auto-detected\n6. **Start command**: override if needed\n7. **Health checks**: configure for zero-downtime deploys\n8. **Custom domain**: CNAME setup\n9. **GitHub integration**: auto-deploy on push\n10. **Deploy environments**: production + staging environments\n11. **Monorepo**: deploy specific service from monorepo\n12. **Viewing logs**: `railway logs`"),
  ("aws-lambda-deploy.md","Deploy AWS Lambda Functions",["aws","lambda","serverless","devops"],"intermediate","Deploy and manage AWS Lambda functions for my serverless backend.\n\nFunctions: [DESCRIBE YOUR FUNCTIONS AND THEIR TRIGGERS]\n\nUsing: AWS CDK (TypeScript) for infrastructure\n\n1. **Lambda function code**: handler structure, cold start optimization\n2. **CDK stack**: define Lambda, IAM role, triggers\n3. **Triggers**:\n   - API Gateway HTTP API\n   - SQS queue trigger\n   - EventBridge schedule\n   - S3 object created\n4. **Layers**: shared dependencies without bundling per function\n5. **Environment variables + SSM Parameter Store**\n6. **VPC config**: if function needs to access RDS\n7. **Provisioned concurrency**: eliminate cold starts for latency-sensitive\n8. **X-Ray tracing**: distributed tracing\n9. **CloudWatch alarms**: error rate, duration, throttles\n10. **CI/CD**: GitHub Actions → CDK deploy"),
  ("nginx-load-test.md","Load Test Infrastructure",["load-testing","k6","infrastructure","performance"],"intermediate","Load test my infrastructure to find the breaking point.\n\nInfrastructure: [DESCRIBE: Nginx + App + DB]\n\nUsing: k6\n\nTest scenarios:\n1. **Smoke test**: 1 VU, 1 minute — verify test script works\n2. **Load test**: ramp to [TARGET] RPS over 5 min, sustain 10 min\n3. **Stress test**: keep increasing until failure — find capacity\n4. **Spike test**: instant jump to 10x normal\n5. **Soak test**: moderate load for 1-2 hours (memory leaks)\n\nMetrics to collect:\n- HTTP request rate, error rate, response times (p50/p95/p99)\n- Server CPU, memory, network\n- Database connections, query latency\n- Redis hit rate\n\nResults analysis: where did it break? What's the fix?\nOutput: complete k6 script for realistic user scenarios."),
  ("caching-infrastructure.md","Design Infrastructure Caching",["caching","cdn","cloudfront","redis"],"advanced","Design a multi-layer caching infrastructure for my application.\n\nApp: [DESCRIBE]\n\nLayer 1 — CDN (Cloudflare or CloudFront):\n1. Cache static assets (JS, CSS, images) at edge\n2. Cache API responses at edge for public content\n3. Cache-Control headers for each asset type\n4. Cache invalidation on deploy\n\nLayer 2 — Nginx caching:\n5. `proxy_cache` for upstream responses\n6. Cache by URL, vary by auth header\n\nLayer 3 — Application cache (Redis):\n7. Cache expensive DB queries\n8. Cache external API responses\n9. Rate limiting counters\n\nLayer 4 — Database cache:\n10. PostgreSQL shared_buffers (25% RAM)\n11. Materialized views for expensive reports\n\nDraw the request flow showing which layer serves each request type."),
  ("log-retention.md","Configure Log Retention and Compliance",["logging","compliance","retention","gdpr"],"intermediate","Configure log retention and management for compliance.\n\nCompliance: [GDPR / HIPAA / SOC2 / none — just best practices]\n\nLog types and retention:\n1. Application logs: 90 days hot, 1 year cold storage\n2. Access logs: 1 year (security audit trail)\n3. Error logs: 1 year with alerting\n4. Security events: 2 years\n5. Business events: indefinite (anonymized after 1 year)\n\nImplement:\n6. Structured logging (JSON, no PII in log messages)\n7. Log levels: control verbosity per environment\n8. Automatic PII detection and redaction\n9. Centralized storage: S3 with lifecycle to Glacier\n10. Access controls: who can query logs (SOC2 requirement)\n11. Audit log: log who accessed the logs\n12. GDPR: ability to delete a user's logs on request"),
  ("multi-region.md","Deploy a Multi-Region Architecture",["multi-region","aws","global","architecture"],"advanced","Design and deploy a multi-region architecture for global availability.\n\nCurrent: Single region [us-east-1]\nGoal: Add [eu-west-1] for European users with < 50ms latency from Europe\n\nDesign:\n1. **DNS routing**: Route 53 latency-based routing (user → nearest region)\n2. **Primary region**: active, handles all writes\n3. **Secondary region**: read replica + static content\n4. **Database**: PostgreSQL streaming replication to secondary\n5. **Read routing**: read from local replica, write to primary\n6. **CDN**: CloudFront (global edge already)\n7. **Session state**: Redis with cross-region sync (ElastiCache Global Datastore)\n8. **Failover**: if primary fails, promote secondary to primary\n9. **Data residency**: European user data stays in EU (GDPR)\n10. **Cost**: estimate the additional monthly cost"),
  ("kubernetes-autoscaling.md","Set Up Kubernetes Autoscaling",["kubernetes","autoscaling","hpa","keda"],"advanced","Set up comprehensive autoscaling for my Kubernetes deployment.\n\nApp: [DESCRIBE YOUR WORKLOAD PATTERN — steady, bursty, schedule-based]\n\n1. **Horizontal Pod Autoscaler (HPA)**:\n   - Scale on CPU utilization > 70%\n   - Scale on custom metrics (queue depth, requests per pod)\n   - Min replicas, max replicas\n   - Scale-down delay (prevent flapping)\n2. **Vertical Pod Autoscaler (VPA)**:\n   - Automatically right-size CPU/memory requests\n   - Off mode for recommendations only\n3. **KEDA** (event-driven autoscaling):\n   - Scale to zero when no traffic\n   - Scale on SQS queue depth\n   - Scale on Kafka consumer lag\n4. **Cluster Autoscaler**:\n   - Add/remove nodes based on pod demand\n   - Node group configuration\n5. **Spot instances**: use spot for bursty workloads\n\nOutput: YAML manifests for all autoscalers."),
  ("devops-platform.md","Build an Internal Developer Platform",["idp","platform","devops","developer-experience"],"advanced","Design an Internal Developer Platform (IDP) for my engineering team.\n\nTeam size: [N engineers]\nCurrent pain points: [DESCRIBE: long deploy times, environment parity, etc.]\n\nPlatform components:\n1. **Self-service infrastructure**: create environments with one command\n2. **Backstage**: service catalog, documentation, runbooks\n3. **Golden paths**: opinionated templates for new services\n4. **Secrets management**: self-service secret storage\n5. **Observability portal**: logs, metrics, traces in one place\n6. **Deployment portal**: see deploy status, trigger deploys, roll back\n7. **Cost portal**: per-team cloud spend visibility\n8. **Runbook automation**: common operations as self-service buttons\n9. **DORA metrics dashboard**: track engineering effectiveness\n10. **On-call scheduler**: PagerDuty integration, fair rotation\n\nStart small: what to build in week 1 vs month 6."),
  ("vpn-setup.md","Set Up a VPN for Database Access",["vpn","security","wireguard","devops"],"intermediate","Set up secure VPN access to my production databases.\n\nUsing: WireGuard (modern, fast, simple)\n\n1. **WireGuard server setup** on a bastion EC2/VPS:\n   - Installation (Ubuntu)\n   - Generate server keys\n   - Interface config (`/etc/wireguard/wg0.conf`)\n   - Enable IP forwarding\n   - iptables rules for routing\n2. **Client config**: generate config for each developer\n3. **Peer management**: add/remove peers without restart\n4. **Routing**: route only production subnets through VPN (split tunneling)\n5. **DNS**: resolve internal hostnames through VPN\n6. **Automation**: script to generate new peer configs\n7. **Security**: key rotation procedure\n8. **Alternative**: AWS Client VPN (managed, per-hour cost)\n\nConnect to: PostgreSQL (port 5432) and Redis (port 6379) without exposing to internet."),
  ("gitops-workflow.md","Implement GitOps with ArgoCD",["gitops","argocd","kubernetes","devops"],"advanced","Implement GitOps workflow using ArgoCD for Kubernetes deployments.\n\nSetup:\n- Kubernetes cluster (EKS / GKE / self-hosted)\n- Multiple environments: dev, staging, production\n\nImplement:\n1. **ArgoCD installation** in the cluster\n2. **App of Apps pattern**: manage multiple apps from one ArgoCD app\n3. **Repository structure**:\n   ```\n   gitops-repo/\n     apps/          # ArgoCD Application definitions\n     environments/\n       dev/         # Kustomize overlays for dev\n       staging/\n       production/\n     base/          # Base Kubernetes manifests\n   ```\n4. **Sync policies**: auto-sync dev, manual approval for production\n5. **Health checks**: define custom health assessment\n6. **Notifications**: Slack on sync/failure\n7. **RBAC**: developer can view, SRE can sync, admin can delete\n8. **Secret management**: Sealed Secrets or External Secrets Operator"),
  ("observability-stack.md","Build Full Observability Stack",["observability","otel","metrics","tracing"],"advanced","Build a complete observability stack (metrics + traces + logs).\n\nUsing: OpenTelemetry + Grafana Stack (LGTM: Loki, Grafana, Tempo, Mimir)\n\n1. **OpenTelemetry SDK** setup in your services (Node.js + Python)\n2. **Auto-instrumentation**: HTTP, DB, Redis, message queues\n3. **Manual spans** for business operations\n4. **Metrics**: counters, histograms, gauges exported to Prometheus\n5. **Traces**: OTLP export to Tempo\n6. **Logs**: structured JSON → Promtail → Loki\n7. **Correlation**: link log lines to traces (trace_id in logs)\n8. **Dashboards**: pre-built Grafana dashboards from grafana.com\n9. **SLOs**: define and track Service Level Objectives\n10. **Alerting**: Grafana unified alerting\n\nDocker Compose for local + Helm charts for production."),
  ("database-devops.md","Database DevOps: Migrations in CI/CD",["database","migrations","ci-cd","devops"],"advanced","Integrate database migrations safely into CI/CD pipeline.\n\nStack: PostgreSQL + Flyway (or Liquibase)\nCI: GitHub Actions\n\n1. **Migration file standards**: naming, rollback scripts, idempotency\n2. **CI**: validate migration syntax on every PR\n3. **Staging deploy**: run migrations before app deploy\n4. **Production**: run migrations before rolling app deploy\n5. **Zero-downtime patterns**:\n   - New column: add nullable first, backfill, add NOT NULL constraint later\n   - Drop column: two-phase (stop reading → deploy → drop)\n   - Rename: expand-contract pattern\n6. **Rollback**: automated rollback if migration fails\n7. **Drift detection**: alert if prod schema differs from expected\n8. **Data migrations**: separate from schema migrations (async job)\n9. **Migration testing**: test against prod data copy weekly\n10. **Permissions**: migration runner has limited privileges"),
  ("ssl-certificate-management.md","Automate SSL Certificate Management",["ssl","automation","certbot","devops"],"intermediate","Automate SSL certificate management at scale.\n\nInfrastructure: [DESCRIBE: how many domains, how managed — Nginx, AWS, Cloudflare]\n\n**Let's Encrypt automation**:\n1. Certbot with `--webroot` or `--dns-cloudflare` challenge\n2. Auto-renewal cron: `0 12 * * * /usr/bin/certbot renew --quiet`\n3. Nginx reload hook after renewal\n4. Wildcard certificates: `*.example.com` with DNS challenge\n\n**AWS Certificate Manager**:\n5. Auto-renewing certificates for ALB/CloudFront\n6. DNS validation (add CNAME record)\n7. Terraform: `aws_acm_certificate` + validation record\n\n**Monitoring**:\n8. Certificate expiry monitoring (alert at 30 days)\n9. Certificate transparency log monitoring\n10. Automated alerting: page on-call if renewal fails\n\nNever have a certificate expire in production again."),
  ("cost-allocation.md","Implement Cloud Cost Allocation Tags",["cost","aws","finops","tagging"],"intermediate","Implement comprehensive cost allocation tagging for AWS resources.\n\nBusiness context: [TEAMS, PROJECTS, COST CENTERS]\n\nTagging strategy:\n1. **Mandatory tags**: Environment, Team, Project, CostCenter, Owner\n2. **AWS Organizations**: tag policies to enforce mandatory tags\n3. **Resource-specific tags**: Service, Version, Tier\n4. **Propagation**: EC2 → EBS, ECS → tasks, RDS → snapshots\n5. **Cost Explorer**: filter and group by tags\n6. **Budgets**: per-team budget with alerts at 80%, 100%, 120%\n7. **Anomaly detection**: alert on unexpected cost spikes\n8. **Showback reports**: monthly cost per team email\n9. **Untagged resource hunting**: find and tag orphaned resources\n10. **Terraform tagging**: `default_tags` in provider config\n\nOutput: tagging policy document + Terraform provider config."),
  ("serverless-monitoring.md","Monitor Serverless Functions",["serverless","monitoring","lambda","devops"],"intermediate","Set up monitoring for my serverless (Lambda/Vercel) functions.\n\nFunctions: [LIST YOUR FUNCTIONS AND THEIR IMPORTANCE]\n\nKey metrics:\n1. **Invocation count**: requests per minute per function\n2. **Error rate**: 4xx, 5xx, unhandled exceptions\n3. **Duration**: p50, p95, p99 cold starts vs warm starts\n4. **Throttling**: when functions are throttled (capacity issue)\n5. **Concurrent executions**: approaching account limit?\n6. **Memory utilization**: right-size memory allocation\n\nAlerting:\n7. Error rate > 1%: Slack alert\n8. Cold start > 2s: investigate provisioned concurrency\n9. Duration > 25s (approaching 30s timeout): alert + optimize\n10. Throttle rate > 0: alert + request limit increase\n\nDashboard: Lambda Insights or Lumigo or custom CloudWatch."),
  ("infrastructure-testing.md","Test Infrastructure as Code",["terraform","testing","inspec","devops"],"advanced","Write tests for my Terraform infrastructure code.\n\nInfrastructure: [DESCRIBE YOUR TERRAFORM RESOURCES]\n\nTesting layers:\n1. **Static analysis**: `terraform validate` + `tflint` + `checkov` (security)\n2. **Unit tests**: `Terratest` — deploy to real AWS sandbox, verify resources\n3. **Policy tests**: OPA (Open Policy Agent) policies for compliance\n4. **Drift detection**: `terraform plan` output — alert if diff exists in prod\n5. **Integration**: real infrastructure test with smoke tests\n6. **Destruction test**: verify `terraform destroy` cleans up cleanly\n\nCI pipeline:\n7. On PR: static analysis + security scan\n8. On merge to main: deploy to staging + integration tests\n9. On tag: deploy to production with manual approval\n\nOutput: Terratest Go test file + GitHub Actions workflow."),
]

for filename, title, tags, difficulty, prompt_text in devops:
    write(cat / filename, make_prompt("devops-cicd", title, tags, difficulty, prompt_text))

# ─── CATEGORY 08: AI/ML INTEGRATION ─────────────────────────────────────────────
cat = PROMPTS / "08-ai-ml-integration"
ai_ml = [
  ("claude-api-basics.md","Get Started with the Claude API",["claude","api","anthropic","integration"],"beginner","Build a complete starter integration with the Anthropic Claude API.\n\nUse case: [DESCRIBE WHAT YOU WANT TO BUILD WITH CLAUDE]\n\n1. **Setup**: install `@anthropic-ai/sdk`, configure API key safely\n2. **Basic completion**: send a message, receive a response\n3. **Streaming**: stream the response token by token (for UI)\n4. **System prompt**: set Claude's role and behavior\n5. **Multi-turn conversation**: maintain chat history correctly\n6. **Model selection**: Haiku (fast/cheap) vs Sonnet (balanced) vs Opus (powerful) vs Fable 5 (latest)\n7. **Parameters**: max_tokens, temperature, top_p\n8. **Error handling**: rate limits, API errors, timeouts\n9. **Cost estimation**: tokens → cost calculation\n10. **Best practices**: prompt caching, batching, async processing\n\nOutput: working Node.js + TypeScript integration with all patterns above."),
  ("rag-system.md","Build a RAG System",["rag","embeddings","vector-db","claude"],"advanced","Build a Retrieval-Augmented Generation (RAG) system using Claude.\n\nDocuments to search: [DESCRIBE YOUR CORPUS — docs, PDFs, codebase, support tickets]\n\nArchitecture:\n1. **Document ingestion**:\n   - Load documents (PDF, Markdown, HTML, code)\n   - Chunk documents (strategies: fixed size, sentence, semantic)\n   - Generate embeddings (Voyage AI or OpenAI embeddings)\n   - Store in vector database (pgvector or Pinecone)\n2. **Query pipeline**:\n   - Embed user query\n   - Vector similarity search (top-K results)\n   - Re-rank results (cross-encoder)\n   - Build context from retrieved chunks\n   - Claude generates answer grounded in context\n3. **Evaluation**: retrieval accuracy, answer faithfulness\n4. **Optimizations**: hybrid search, metadata filtering, hypothetical document embeddings\n\nNode.js + TypeScript implementation."),
  ("prompt-engineering.md","Advanced Prompt Engineering for Claude",["prompts","engineering","techniques","claude"],"intermediate","Master advanced prompt engineering techniques for Claude.\n\nTask: [DESCRIBE YOUR TASK]\n\nTechniques to apply:\n1. **Chain of Thought (CoT)**: \"Let's think step by step\"\n2. **Few-shot examples**: show 3 examples of input → desired output\n3. **Output format control**: JSON, XML, specific structure\n4. **Role specification**: \"You are an expert [X] with [N] years experience\"\n5. **Constraint specification**: what NOT to do\n6. **Verification step**: ask Claude to check its own work\n7. **Multi-step decomposition**: break complex tasks into steps\n8. **Calibration prompts**: ask for confidence + reasoning\n9. **XML tags for Claude**: `<context>`, `<task>`, `<format>` structure\n10. **Extended thinking** (Claude Fable 5): enable deep reasoning\n\nFor MY task: the optimized prompt with each technique applied."),
  ("ai-agents.md","Build AI Agents with Claude",["agents","tools","claude","ai"],"advanced","Build an AI agent system using Claude with tool use.\n\nAgent purpose: [DESCRIBE: research agent, coding agent, data analysis agent, customer service]\n\nImplement:\n1. **Tool definition**: define tools as JSON schema (Claude understands these)\n2. **Tool examples**:\n   - `search_web(query)` → results\n   - `execute_code(code)` → output\n   - `read_file(path)` → content\n   - `query_database(sql)` → results\n3. **Agentic loop**: Claude → tool call → result → Claude → ... → final answer\n4. **Multi-agent**: orchestrator agent + specialist sub-agents\n5. **Memory**: short-term (conversation), long-term (vector DB)\n6. **Error handling**: tool failures, retries, fallbacks\n7. **Safety guardrails**: what agents are NOT allowed to do\n8. **Observation and logging**: trace every action for debugging\n\nNode.js implementation with the Anthropic SDK."),
  ("langchain-integration.md","Build with LangChain and Claude",["langchain","claude","ai","chains"],"advanced","Build a LangChain application using Claude as the LLM.\n\nApplication: [DESCRIBE YOUR USE CASE]\n\nUsing: LangChain.js (or Python)\n\n1. **Claude LLM setup**: `ChatAnthropic` with model selection\n2. **Prompt templates**: `ChatPromptTemplate` with variables\n3. **Chains**: LCEL (LangChain Expression Language) pipe syntax\n4. **Retrieval chain**: RAG with document loader + splitter + vector store\n5. **Conversational retrieval**: memory + retrieval for chat over docs\n6. **Agents**: Claude-powered agent with web search tool\n7. **Output parsers**: structured output (JSON, Pydantic)\n8. **Callbacks**: streaming, logging, token counting\n9. **Memory**: ConversationBufferMemory, VectorStoreMemory\n10. **LangSmith**: tracing and debugging your chain\n\nOutput: complete application with all components."),
  ("ai-content-pipeline.md","Build an AI Content Generation Pipeline",["content","generation","claude","automation"],"intermediate","Build an automated content generation pipeline using Claude.\n\nContent type: [DESCRIBE: blog posts, product descriptions, social media, emails]\nInput: [DESCRIBE: product data, topics list, customer segment]\nOutput: [DESCRIBE DESIRED FORMAT]\n\nPipeline:\n1. **Input processing**: parse and validate input data\n2. **Prompt construction**: dynamic prompt with input variables\n3. **Parallel generation**: generate N pieces of content concurrently\n4. **Quality filtering**: Claude self-evaluates each piece, reject below threshold\n5. **Human review queue**: flag borderline content for review\n6. **Post-processing**: format, add metadata, validate output schema\n7. **Storage**: save to CMS or database\n8. **Rate limiting**: respect Claude API rate limits\n9. **Cost tracking**: track tokens and cost per run\n10. **Monitoring**: alert on high rejection rates\n\nNode.js implementation with BullMQ for queuing."),
  ("document-analysis.md","Build a Document Analysis System",["documents","pdf","analysis","claude"],"intermediate","Build a system to analyze and extract information from documents.\n\nDocument types: [PDFs, Word docs, Excel, emails, etc.]\nExtraction goal: [DESCRIBE: extract key data points, summarize, classify, compare]\n\nImplement:\n1. **Document loading**: PDF parsing (pdf-parse), DOCX (mammoth), Excel (xlsx)\n2. **Text extraction**: preserve structure (headings, tables, lists)\n3. **Claude analysis prompt**: extract specific structured data\n4. **Structured output**: force JSON output with schema validation\n5. **Table extraction**: extract tables as structured data\n6. **Multi-document comparison**: compare N documents for differences\n7. **Citation extraction**: identify and validate citations\n8. **PII detection**: find and flag personal information\n9. **Batch processing**: process hundreds of documents efficiently\n10. **Output formats**: JSON, CSV, structured database records\n\nNode.js + TypeScript with Zod validation."),
  ("chatbot-system.md","Build a Production Chatbot",["chatbot","claude","conversational-ai","nlp"],"advanced","Build a production-grade AI chatbot powered by Claude.\n\nBot purpose: [DESCRIBE: customer support, internal knowledge base, onboarding]\nKnowledge base: [DESCRIBE YOUR CONTENT]\n\n1. **System prompt engineering**: persona, tone, capabilities, guardrails\n2. **Context management**: conversation history with token budget\n3. **RAG integration**: retrieve relevant knowledge base articles\n4. **Intent classification**: route to specialized handlers (FAQ, human escalation)\n5. **Guardrails**: refuse off-topic, harmful, or confidential-info requests\n6. **Escalation**: hand off to human agent with conversation summary\n7. **Multi-language**: detect language, respond in same language\n8. **Feedback collection**: thumbs up/down → improve prompts\n9. **Analytics**: most common questions, satisfaction score\n10. **A/B testing**: compare different system prompts\n\nReact UI + Node.js backend with streaming."),
  ("text-classification.md","Build a Text Classification System",["classification","nlp","claude","ml"],"intermediate","Build a text classification system using Claude.\n\nClassification task: [DESCRIBE: sentiment analysis, topic classification, spam detection, intent recognition]\nLabels: [LIST YOUR CATEGORIES]\nInput volume: [EXPECTED VOLUME]\n\n1. **Zero-shot classification**: no examples needed (Claude understands)\n2. **Few-shot classification**: provide examples for better accuracy\n3. **Multi-label classification**: a document can belong to multiple categories\n4. **Hierarchical classification**: coarse → fine-grained classification\n5. **Confidence scores**: estimate confidence, flag low-confidence for review\n6. **Batch processing**: classify thousands efficiently with caching\n7. **Evaluation**: measure accuracy against labeled test set\n8. **Confusion matrix**: which categories does the model confuse?\n9. **Cost optimization**: cache results, use Haiku for simple cases\n10. **Fine-tuning alternative**: when to use Claude vs a fine-tuned smaller model\n\nPython implementation with async batching."),
  ("ai-code-review.md","Build an AI Code Review Tool",["code-review","claude","ai","development"],"advanced","Build an AI-powered code review tool using Claude.\n\nReview focus: [SECURITY / PERFORMANCE / STYLE / ALL]\nLanguages: [LIST]\n\n1. **GitHub PR integration**: webhook → fetch diff → analyze → comment\n2. **Review prompt**: analyze for bugs, security issues, performance, style\n3. **Structured output**: list of issues with: file, line, severity, description, suggestion\n4. **Severity levels**: critical (must fix), major (should fix), minor (nice to fix)\n5. **Context loading**: load related files for better analysis\n6. **Auto-fix suggestions**: generate corrected code for simple issues\n7. **False positive reduction**: learn from reviewer dismissals\n8. **GitHub PR comments**: post inline comments on specific lines\n9. **Summary comment**: overall assessment at top of PR\n10. **Rate limiting**: respect both Claude and GitHub API limits\n\nGitHub App implementation."),
  ("semantic-search.md","Build Semantic Search",["search","embeddings","vector-db","claude"],"advanced","Build semantic search for my content.\n\nContent to search: [DESCRIBE YOUR DATA]\nExpected queries: [DESCRIBE WHAT USERS WILL SEARCH FOR]\n\n1. **Embeddings**: choose embedding model (Voyage AI for best quality)\n2. **Chunking strategy**: optimal chunk size for your content type\n3. **Vector store**: pgvector (PostgreSQL) vs Pinecone vs Weaviate\n4. **Indexing pipeline**: new content → embed → store\n5. **Search**: embed query → similarity search → retrieve top-K\n6. **Hybrid search**: combine BM25 (keyword) + semantic for best results\n7. **Re-ranking**: use cross-encoder to re-rank top-20 → top-5\n8. **Metadata filtering**: filter by date, category, author before vector search\n9. **Query expansion**: use Claude to generate alternative queries\n10. **Evaluation**: recall@K, NDCG metrics\n11. **Result display**: highlight matching terms, show source\n\nFull implementation with Node.js + pgvector."),
  ("ai-moderation.md","Build AI Content Moderation",["moderation","safety","claude","content"],"advanced","Build an AI content moderation system using Claude.\n\nContent types to moderate: [DESCRIBE: text posts, images, user bios, comments]\nViolation categories: [SPAM / HATE / ADULT / VIOLENCE / OTHER]\n\n1. **Text moderation**: classify content by violation type\n2. **Severity scoring**: 0-1 score for each category\n3. **Action triggers**: auto-remove (high severity) vs human review (medium) vs allow (low)\n4. **Context awareness**: same text may be ok in one community, not another\n5. **Appeal system**: users can appeal, human reviews with AI suggestion\n6. **Consistency**: same content → same decision (deterministic where possible)\n7. **Adversarial inputs**: detect attempts to bypass moderation\n8. **Performance**: < 100ms for text moderation (use Haiku)\n9. **Audit log**: every decision logged with reasoning\n10. **Calibration**: track false positive rate, adjust thresholds"),
  ("data-extraction.md","Extract Structured Data from Unstructured Text",["extraction","nlp","structured-data","claude"],"intermediate","Extract structured data from unstructured text using Claude.\n\nInput text type: [DESCRIBE: receipts, resumes, medical notes, legal contracts, emails]\nData to extract: [LIST FIELDS TO EXTRACT]\n\n1. **Define output schema** (TypeScript interface or Zod schema)\n2. **Extraction prompt**: precise instructions for each field\n3. **JSON mode**: force structured JSON output\n4. **Validation**: Zod validate the extracted data\n5. **Handling missing data**: null vs \"not mentioned\" vs inferred\n6. **Tables extraction**: extract tabular data from text\n7. **Multiple records**: extract list of items from one document\n8. **Accuracy**: handle typos, abbreviations, different formats\n9. **Normalization**: dates → ISO 8601, currencies → decimal\n10. **Confidence**: flag fields where extraction is uncertain\n\nBatch processing for high volume."),
  ("ai-summarization.md","Build Text Summarization Features",["summarization","claude","nlp","content"],"intermediate","Add AI summarization to my application.\n\nContent to summarize: [DESCRIBE: articles, meeting transcripts, reports, emails]\nSummary format: [BULLET POINTS / PARAGRAPH / STRUCTURED SECTIONS]\nAudience: [WHO WILL READ THE SUMMARY]\n\n1. **Summary types**:\n   - Executive summary: 3 bullet points for busy readers\n   - Detailed summary: preserves all key points\n   - Meeting minutes: action items, decisions, attendees\n   - Abstractive: new sentences (not copied from original)\n2. **Long document handling**: chunk → summarize each → meta-summarize\n3. **Key points extraction**: numbered list of most important points\n4. **Action items**: extract TODO items from meeting notes\n5. **Sentiment**: add overall tone (positive/negative/neutral)\n6. **Multilingual**: summarize in a different language\n7. **Custom length**: user controls word count\n8. **Citation**: which part of original supports each summary point\n\nReact component + backend API."),
  ("ai-translation.md","Build AI-Powered Translation",["translation","multilingual","claude","nlp"],"intermediate","Add AI-powered translation and localization to my app.\n\nUse case: [DESCRIBE: user content, UI strings, documents, real-time chat]\nLanguage pairs: [SOURCE → TARGET LANGUAGES]\n\n1. **Basic translation**: Claude translates between any language pair\n2. **Context-aware**: provide surrounding context for better translation\n3. **Tone preservation**: formal vs informal, brand voice\n4. **Domain-specific**: legal, medical, technical — use domain vocabulary\n5. **Glossary**: maintain consistent translation of key terms\n6. **Transliteration**: romanize scripts (Arabic, Chinese, etc.)\n7. **Back-translation**: verify quality by translating back\n8. **Streaming**: stream translation for real-time feel\n9. **Caching**: cache translations to reduce API calls\n10. **Quality evaluation**: BLEU score approximation\n\nIntegrate with i18next for UI string management."),
  ("ai-question-answering.md","Build a Question Answering System",["qa","claude","knowledge-base","rag"],"intermediate","Build a question answering system over my knowledge base.\n\nKnowledge base: [DESCRIBE: documentation, FAQ, product manual, internal wiki]\nUser types: [DESCRIBE WHO WILL ASK QUESTIONS]\n\n1. **Document indexing**: chunk and embed all documents\n2. **Question understanding**: rephrase/expand question for better retrieval\n3. **Context retrieval**: find most relevant document sections\n4. **Answer generation**: Claude answers using ONLY retrieved context\n5. **Citation**: cite which document/section the answer comes from\n6. **\"I don't know\"**: Claude admits when answer isn't in the knowledge base\n7. **Followup handling**: conversational Q&A with memory\n8. **Confidence**: flag uncertain answers for human review\n9. **Analytics**: most common questions → improve documentation\n10. **Feedback loop**: thumbs up/down improves retrieval over time\n\nFull-stack implementation."),
  ("ai-code-generation.md","Build an AI Code Generation Tool",["code-generation","claude","developer-tools","ai"],"advanced","Build an AI code generation and explanation tool.\n\nUse case: [DESCRIBE: generate boilerplate, explain code, convert between languages, refactor]\nLanguage focus: [PROGRAMMING LANGUAGES]\n\n1. **Code generation**: from natural language description → working code\n2. **Multi-file generation**: generate an entire feature spanning multiple files\n3. **Code explanation**: explain what this code does, line by line\n4. **Code refactoring**: improve readability, performance, patterns\n5. **Language conversion**: Python → TypeScript, SQL → code, etc.\n6. **Test generation**: generate unit tests for existing code\n7. **Documentation**: generate JSDoc/docstrings for functions\n8. **Debugging help**: identify bugs and suggest fixes\n9. **Code review**: review for security, performance, style issues\n10. **Interactive REPL**: user iterates on generated code in conversation\n\nUI with Monaco editor (VS Code in browser)."),
  ("computer-vision.md","Integrate Vision AI into Your App",["vision","images","claude","multimodal"],"advanced","Integrate Claude's vision capabilities into my application.\n\nUse case: [DESCRIBE: product image analysis, document scanning, screenshot understanding, medical imaging]\n\n1. **Image input**: send images to Claude (URL or base64)\n2. **Image description**: generate detailed description of image content\n3. **Object detection**: identify and list objects in the image\n4. **Document OCR**: extract text from documents and receipts\n5. **Data extraction from images**: extract structured data from forms/tables\n6. **Image comparison**: compare two images, describe differences\n7. **UI analysis**: analyze screenshot, generate code to recreate it\n8. **Chart understanding**: extract data from charts and graphs\n9. **Batch processing**: analyze hundreds of images efficiently\n10. **Caching**: cache analysis results to avoid re-processing same image\n\nNode.js + TypeScript implementation with Claude's multimodal API."),
  ("ai-writing-assistant.md","Build an AI Writing Assistant",["writing","assistant","claude","nlp"],"intermediate","Build an AI writing assistant for [DESCRIBE YOUR PLATFORM: blog, email, code comments, etc.].\n\nFeatures:\n1. **Grammar correction**: fix errors while preserving voice\n2. **Tone adjustment**: rewrite as formal, casual, professional, friendly\n3. **Expansion**: make this paragraph longer with more detail\n4. **Condensation**: make this shorter, get to the point\n5. **Subject line generation**: given email body, generate 5 subject options\n6. **Headline generation**: SEO-optimized headlines for blog posts\n7. **Completion**: continue writing from where user stopped\n8. **Rephrasing**: say this differently (offer 3 options)\n9. **Plagiarism check** (heuristic): flag if output looks copied\n10. **Brand voice**: learn brand guidelines, apply to all rewrites\n\nReact integration with selection-based actions (like Notion AI)."),
  ("ai-analytics.md","Add AI-Powered Analytics",["analytics","ai","claude","insights"],"advanced","Add AI-powered analytics and insights to my business application.\n\nData available: [DESCRIBE YOUR METRICS AND DATABASES]\nBusiness questions to answer: [LIST 5-10 KEY BUSINESS QUESTIONS]\n\n1. **Natural language to SQL**: Claude converts business questions to SQL queries\n2. **Query execution**: run the SQL safely (read-only role)\n3. **Result interpretation**: Claude explains what the numbers mean\n4. **Anomaly detection**: flag unusual patterns in metrics\n5. **Trend analysis**: identify and explain trends over time\n6. **Prediction**: simple forecasting (Claude + statistical method)\n7. **Automated insights**: weekly AI-generated insights report\n8. **Comparative analysis**: compare periods, segments, cohorts\n9. **Root cause analysis**: why did metric X drop this week?\n10. **Chart recommendations**: which visualization best shows this data?\n\nSafety: read-only database access, query validation."),
  ("ai-personalization.md","Build AI-Powered Personalization",["personalization","recommendations","claude","ai"],"advanced","Build an AI personalization system for my platform.\n\nPlatform type: [E-COMMERCE / CONTENT / LEARNING / OTHER]\nUser data available: [DESCRIBE: behavior, preferences, demographics, history]\n\n1. **User profile building**: summarize user interests from behavior\n2. **Content recommendations**: find items matching user profile\n3. **Collaborative filtering**: users similar to you also liked...\n4. **Explanation**: \"We recommend this because...\"\n5. **Diversity**: avoid filter bubble (mix familiar + new)\n6. **Cold start**: new users with no history\n7. **Contextual**: time of day, device, location adjustments\n8. **Real-time**: recommendations update as user interacts\n9. **A/B testing**: compare AI recommendations vs rule-based\n10. **Feedback**: thumbs up/down to refine recommendations\n\nClaude + embeddings for user/item matching."),
  ("claude-tool-use.md","Master Claude Tool Use (Function Calling)",["tool-use","function-calling","claude","agents"],"advanced","Master Claude's tool use (function calling) feature.\n\nTools to implement: [DESCRIBE WHAT TOOLS YOUR AGENT NEEDS]\n\n1. **Tool definition**: name, description, input_schema (JSON Schema)\n2. **Tool examples**:\n   ```\n   get_weather(city: string) → temperature, conditions\n   search_database(query: string, table: string) → results\n   send_email(to: string, subject: string, body: string) → success\n   create_calendar_event(title, start, end, attendees) → event_id\n   ```\n3. **Parallel tool use**: Claude calls multiple tools simultaneously\n4. **Tool error handling**: tool fails → inform Claude → it adapts\n5. **Confirmation pattern**: ask user before executing irreversible tools\n6. **Tool result formatting**: how to structure results for Claude\n7. **Chain of tools**: multi-step tasks using multiple tools\n8. **Safety**: validate tool inputs before executing\n9. **Logging**: audit trail of every tool call\n10. **Streaming with tool use**: handle streaming when tools are involved\n\nNode.js SDK implementation."),
  ("ai-testing.md","Test AI-Powered Features",["testing","ai","llm","evaluation"],"advanced","Design a testing strategy for AI-powered features.\n\nAI feature to test: [DESCRIBE YOUR AI FEATURE]\n\nChallenges with AI testing:\n- Non-deterministic: same input → different output each time\n- Hard to assert: what is a \"correct\" response?\n- Expensive: can't run LLM calls in unit tests\n- Prompt regression: changing prompt changes behavior unpredictably\n\nTesting strategies:\n1. **Mock Claude**: return canned responses in unit tests\n2. **Eval datasets**: 100 input/expected-output pairs, run weekly\n3. **LLM judge**: use Claude to evaluate Claude's own outputs\n4. **Property tests**: test properties (length, format, tone) not exact text\n5. **Regression testing**: compare new vs old prompt on same inputs\n6. **Human evaluation**: periodic human review of 50 random outputs\n7. **Red teaming**: adversarial inputs trying to break the system\n8. **Latency testing**: measure p95 latency under load\n9. **Cost regression**: alert if tokens per request increases 20%+\n10. **Shadow mode**: run new prompt alongside old, compare before switching"),
  ("ai-cost-optimization.md","Optimize AI API Costs",["cost","optimization","claude","tokens"],"intermediate","Optimize my Claude API usage costs without sacrificing quality.\n\nCurrent usage: [DESCRIBE: how many calls/day, average tokens, which models]\nCurrent monthly cost: [ESTIMATE]\n\nOptimization strategies:\n1. **Prompt caching**: cache shared system prompts (90% token discount)\n2. **Model routing**: use Haiku for simple tasks, Sonnet for medium, Opus for complex\n3. **Input compression**: remove unnecessary whitespace, abbreviate where safe\n4. **Output length control**: `max_tokens` limits runaway outputs\n5. **Batching**: batch API for non-real-time use cases (50% discount)\n6. **Caching responses**: cache Claude responses for identical inputs (Redis)\n7. **Streaming**: stream to user (doesn't affect cost, but better UX)\n8. **Avoid retries on same prompt**: use exponential backoff for errors only\n9. **Pre-computation**: generate and cache content in advance\n10. **Monitor**: track cost per user, per feature, alert on anomalies\n\nTarget: 50% cost reduction. Show the math."),
  ("multi-modal-app.md","Build a Multimodal AI App",["multimodal","vision","claude","images"],"advanced","Build a multimodal application using Claude's text + vision capabilities.\n\nApplication: [DESCRIBE: photo analysis app, document processor, visual Q&A, design feedback tool]\n\n1. **File upload**: support images (JPEG, PNG, WebP, GIF) and PDFs\n2. **Image preprocessing**: resize large images (< 5MB limit), convert format\n3. **PDF handling**: extract pages as images for vision analysis\n4. **Vision API call**: send image + text prompt to Claude\n5. **Structured extraction**: extract structured data from images\n6. **Multiple images**: compare multiple images in one prompt\n7. **Conversation over image**: multi-turn conversation about uploaded image\n8. **Caching**: cache analysis for same image hash\n9. **Access control**: ensure users can only see their own uploaded images\n10. **Usage tracking**: track image processing costs separately\n\nFull-stack implementation."),
  ("claude-fable5-features.md","Leverage Claude Fable 5 Unique Features",["fable-5","extended-thinking","claude","advanced"],"advanced","Leverage Claude Fable 5's unique capabilities for advanced tasks.\n\nTasks requiring Fable 5: [DESCRIBE YOUR COMPLEX TASKS]\n\n1. **Extended thinking**: enable for complex reasoning tasks\n   - Set `thinking: {type: 'enabled', budget_tokens: 10000}`\n   - Show thinking in UI or hide it (stream_thinking vs stream_text)\n   - Use cases: math, logic, code architecture, complex analysis\n2. **200K context window**: send entire codebases or long documents\n3. **Superior code generation**: complex algorithms, architecture\n4. **Advanced reasoning**: multi-step logical problems\n5. **Tool use with thinking**: agent thinks before using tools\n6. **Long-form writing**: coherent long documents, books, reports\n7. **Complex analysis**: compare large datasets, find patterns\n8. **Calibration**: Fable 5 knows what it doesn't know\n\nWhen to use Fable 5 vs Sonnet 4 vs Haiku 3.5 — decision matrix."),
  ("ai-workflow-automation.md","Build AI-Powered Workflow Automation",["workflow","automation","claude","agents"],"advanced","Build an AI-powered workflow automation system.\n\nWorkflows to automate: [DESCRIBE: data processing, content moderation, report generation, etc.]\n\n1. **Workflow definition**: define steps, triggers, conditions\n2. **Claude as orchestrator**: plan the workflow steps dynamically\n3. **Tool integrations**: connect Claude to: database, APIs, email, Slack, calendar\n4. **Human-in-the-loop**: pause for human review when confidence is low\n5. **Error recovery**: Claude handles errors, tries alternative approaches\n6. **State management**: persist workflow state across multiple Claude calls\n7. **Parallel execution**: run independent workflow steps simultaneously\n8. **Logging and observability**: trace every decision and action\n9. **Approval gates**: require human approval for high-impact actions\n10. **Testing**: replay recorded workflows to test changes\n\nNode.js + LangChain or custom implementation."),
  ("prompt-caching.md","Implement Claude Prompt Caching",["caching","claude","optimization","tokens"],"intermediate","Implement Claude's prompt caching feature to reduce costs and latency.\n\nUse cases with large system prompts or repeated context: [DESCRIBE]\n\n1. **What gets cached**: system prompt + any content before the last user message\n2. **Cache breakpoint**: mark where to cache with `cache_control: {type: 'ephemeral'}`\n3. **Cache window**: 5 minutes (extended with usage)\n4. **Cost**: input tokens 90% cheaper when served from cache\n5. **Latency**: cached tokens skip processing (faster TTFT)\n6. **Pattern 1**: long system prompt with instructions + knowledge\n7. **Pattern 2**: many-shot examples prepended to every request\n8. **Pattern 3**: entire document as context for Q&A\n9. **Measuring**: cache hits in API response headers\n10. **Multi-turn**: cache grows as conversation continues\n\nCalculate ROI: cost savings for your specific usage pattern."),
  ("ai-evaluation.md","Evaluate and Improve Your AI Features",["evaluation","llm","quality","metrics"],"advanced","Build an evaluation framework for your AI-powered features.\n\nAI feature to evaluate: [DESCRIBE]\n\n1. **Eval dataset**: curate 200 representative test cases\n   - Happy path inputs\n   - Edge cases\n   - Adversarial inputs\n   - Common failure modes\n2. **Metrics**:\n   - Task success rate\n   - Response quality (LLM judge 1-5)\n   - Helpfulness (LLM judge)\n   - Hallucination rate\n   - Latency p50/p95\n   - Cost per successful task\n3. **LLM judge**: use Claude to score Claude's outputs against rubric\n4. **Regression tracking**: track metrics over time, alert on drops\n5. **Prompt experimentation**: A/B test prompt variants against eval set\n6. **Error analysis**: cluster failures by type, identify patterns\n7. **Human baseline**: how well would a human do this task?\n\nAutomated eval pipeline in CI that runs weekly."),
  ("vector-database.md","Set Up and Use a Vector Database",["vector-db","pgvector","pinecone","embeddings"],"advanced","Set up a vector database for AI/ML applications.\n\nUse case: [DESCRIBE: semantic search, RAG, recommendation, deduplication]\nData to vectorize: [DESCRIBE]\nScale: [EXPECTED RECORD COUNT]\n\nOption A — pgvector (PostgreSQL extension):\n1. Install: `CREATE EXTENSION vector`\n2. Column type: `embedding vector(1536)`\n3. IVFFlat index: `CREATE INDEX ON items USING ivfflat (embedding vector_cosine_ops)`\n4. HNSW index: faster search, more memory\n5. Query: `ORDER BY embedding <-> $1 LIMIT 10`\n6. Hybrid: combine with PostgreSQL FTS\n\nOption B — Pinecone (managed):\n7. Namespace for isolation\n8. Metadata filtering\n9. Sparse-dense hybrid\n\nFor my scale and query patterns: which to use and why?\nFull indexing + query implementation."),
  ("ai-fine-tuning.md","Fine-Tune a Model for Your Task",["fine-tuning","ml","training","claude"],"advanced","Design a fine-tuning strategy for my specialized task.\n\nTask: [DESCRIBE YOUR TASK]\nWhy fine-tuning: [DESCRIBE WHY PROMPTING ALONE ISN'T ENOUGH]\n\nNote: Claude API doesn't support fine-tuning (use Anthropic commercial agreements or another model)\n\nAlternatives to fine-tuning first:\n1. **Better prompting**: few-shot examples, chain-of-thought\n2. **RAG**: add domain knowledge without training\n3. **Prompt caching**: large few-shot set without cost\n\nIf fine-tuning is the right choice (open-source model):\n4. **Dataset preparation**: format, quality, quantity requirements\n5. **Base model selection**: Llama 3, Mistral, Phi-3\n6. **Fine-tuning method**: LoRA / QLoRA (efficient)\n7. **Training**: Google Colab, AWS EC2 GPU\n8. **Evaluation**: compare fine-tuned vs base model on your eval set\n9. **Serving**: Ollama local, Modal or HuggingFace for cloud"),
  ("ai-security.md","Secure Your AI Application",["security","ai","prompt-injection","claude"],"advanced","Secure my AI application against prompt injection and abuse.\n\nApp: [DESCRIBE YOUR AI FEATURE]\n\nThreats:\n1. **Prompt injection**: user input overrides system prompt\n   - Defense: XML tags around user input, clear delimiters\n   - Defense: validate Claude's output before acting on it\n2. **Jailbreaking**: bypass safety guidelines\n   - Defense: Claude's built-in safety is strong, add extra layer\n3. **Data exfiltration**: get Claude to reveal system prompt or training data\n   - Defense: never put secrets in system prompt\n4. **Resource exhaustion**: max_tokens abuse\n   - Defense: output length limits per user tier\n5. **Content policy violations**: generate harmful content\n   - Defense: output scanning before displaying\n6. **Cost attacks**: trigger expensive requests\n   - Defense: rate limiting, cost per user limit\n7. **Indirect injection**: malicious content in RAG documents injected into prompt\n   - Defense: sanitize retrieved content\n\nImplement all defenses in code."),
  ("ai-streaming.md","Stream AI Responses in Real-Time",["streaming","claude","ux","real-time"],"intermediate","Implement real-time streaming of Claude responses for great UX.\n\nUI framework: [React / Next.js / Vue]\n\nBackend (Node.js):\n1. Claude streaming API: `stream: true`\n2. Event types: `message_start`, `content_block_delta`, `message_stop`\n3. SSE endpoint: forward Claude stream to frontend\n4. Error handling mid-stream\n5. Abort: cancel stream when user clicks stop button\n\nFrontend (React):\n6. Fetch with ReadableStream\n7. Append tokens to state as they arrive\n8. Show typing indicator while waiting for first token\n9. Auto-scroll to bottom\n10. Stop button: abort fetch, stop stream\n\nEdge deployment:\n11. Vercel Edge Functions for minimal latency\n12. OpenAI-compatible streaming format for compatibility\n\nFull implementation with beautiful streaming chat UI."),
  ("ai-pipeline-orchestration.md","Orchestrate AI Pipelines",["orchestration","pipelines","claude","agents"],"advanced","Build a complex AI pipeline that chains multiple Claude calls.\n\nPipeline goal: [DESCRIBE YOUR MULTI-STEP AI WORKFLOW]\n\n1. **Pipeline definition**: graph of steps with dependencies\n2. **Step types**: transform, classify, generate, validate, branch\n3. **Data flow**: output of step N → input of step N+1\n4. **Parallelism**: run independent steps in parallel\n5. **Branching**: different paths based on step output\n6. **Validation gates**: validate output before passing to next step\n7. **Retry logic**: retry failed steps with different approach\n8. **State persistence**: save pipeline state (can resume if interrupted)\n9. **Cost tracking**: track tokens per step\n10. **Visualization**: diagram of pipeline execution\n11. **Testing**: unit test each step independently\n12. **Monitoring**: latency and success rate per step\n\nNode.js implementation with a DAG executor."),
  ("ai-feedback-loop.md","Build an AI Feedback and Learning Loop",["feedback","ai","improvement","mlops"],"advanced","Build a feedback loop to continuously improve your AI features.\n\nAI feature: [DESCRIBE]\n\n1. **Implicit feedback**: track engagement signals (did user accept the suggestion?)\n2. **Explicit feedback**: thumbs up/down on AI responses\n3. **Feedback storage**: log: input, output, user_action, timestamp\n4. **Failure analysis**: weekly review of thumbs-down responses\n5. **Prompt improvement**: use failures to improve prompts (human-in-the-loop)\n6. **A/B testing framework**: compare prompt variants on live traffic\n7. **Statistical significance**: how many samples before declaring winner\n8. **Automated improvement**: use Claude to suggest prompt improvements based on failures\n9. **Regression prevention**: eval set that catches any new regressions\n10. **Quality metrics over time**: track improvement rate\n\nDashboard showing: satisfaction rate, top failure categories, prompt history."),
  ("knowledge-graph.md","Build a Knowledge Graph with AI",["knowledge-graph","neo4j","ai","claude"],"advanced","Build a knowledge graph powered by AI extraction.\n\nSource content: [DESCRIBE: documents, articles, research papers]\nKnowledge to extract: [ENTITIES, RELATIONSHIPS]\n\n1. **Entity extraction**: Claude identifies named entities (people, orgs, concepts, products)\n2. **Relationship extraction**: Claude identifies relationships between entities\n3. **Coreference resolution**: \"he\" refers to \"CEO John Smith\"\n4. **Entity deduplication**: \"Apple Inc\" and \"Apple\" are the same entity\n5. **Confidence scoring**: flag low-confidence extractions for review\n6. **Graph storage**: Neo4j for property graph\n7. **Graph queries**: find connections, shortest path, influential nodes\n8. **Visualization**: interactive graph UI (vis.js or D3 force graph)\n9. **Updates**: add new documents without duplicating existing entities\n10. **Export**: SPARQL-compatible RDF format\n\nPython implementation with async processing."),
  ("ai-error-handling.md","Handle AI Errors Gracefully",["error-handling","claude","reliability","api"],"intermediate","Handle all error scenarios in my Claude API integration gracefully.\n\nError types to handle:\n1. **Rate limit (429)**: exponential backoff: 1s, 2s, 4s, 8s, 16s, give up\n2. **Overloaded (529)**: server busy — retry with longer delay\n3. **Invalid request (400)**: prompt too long, invalid parameters — don't retry, fix it\n4. **Auth error (401)**: invalid API key — alert, don't retry\n5. **Timeout**: stream stalls — detect with timeout, abort and retry\n6. **Partial response**: stream cut off mid-sentence — detect and complete or retry\n7. **Content policy**: Claude refuses the request — graceful fallback message\n8. **JSON parsing**: Claude returns malformed JSON — retry with stronger format instruction\n9. **Token limit**: response truncated — detect and request continuation\n10. **Network errors**: ECONNRESET, etc. — retry with backoff\n\nReusable retry wrapper for all Claude API calls."),
  ("ai-local.md","Run AI Models Locally",["local-ai","ollama","llama","offline"],"intermediate","Run AI models locally for development and privacy.\n\nUse case: [DESCRIBE: development, privacy-sensitive data, offline use, cost reduction]\n\nUsing: Ollama\n\n1. **Installation**: `curl -fsSL https://ollama.ai/install.sh | sh`\n2. **Pull models**: `ollama pull llama3.1:8b`, `ollama pull mistral`, `ollama pull codellama`\n3. **Ollama API**: OpenAI-compatible REST API at localhost:11434\n4. **Integration**: drop-in replacement for OpenAI SDK\n5. **Model selection guide**: which model for which task\n6. **GPU acceleration**: NVIDIA CUDA, Apple Metal (M1/M2)\n7. **Context length**: manage smaller context windows\n8. **Quantization**: Q4_K_M (smallest), Q8_0 (quality), F16 (full)\n9. **Modelfile**: customize system prompt, temperature\n10. **LM Studio**: GUI alternative to Ollama\n\nCompare: local vs Claude API — when each makes sense."),
  ("ai-structured-output.md","Get Reliable Structured Output from Claude",["structured-output","json","validation","claude"],"intermediate","Get reliable structured JSON output from Claude every time.\n\nData structure needed: [DESCRIBE YOUR TARGET JSON SCHEMA]\n\nTechniques (from fragile to reliable):\n\n1. **Basic**: ask for JSON in the prompt\n2. **Schema in prompt**: include your JSON schema with descriptions\n3. **Few-shot examples**: show 2-3 examples of correct JSON output\n4. **XML wrapping**: ask Claude to wrap JSON in `<json>` tags (parse easily)\n5. **Validation + retry**: if Zod validation fails, send error back to Claude\n6. **Format reminder**: end prompt with \"Remember: respond ONLY with valid JSON\"\n7. **Temperature 0**: for consistency in structured tasks\n8. **Output type in system prompt**: tell Claude its output type from the start\n9. **Anthropic beta JSON mode**: if available, use tool_use with defined schema\n10. **Post-processing**: fix common JSON mistakes (trailing commas, unquoted keys)\n\nReusable TypeScript function for each approach."),
]

